// One sheet of drafting paper unrolls from the tilted roll and stops with the
// three building plans laid out on it.
const slot_first = -2.05;
const slot_width = 2.6;
const paper_length = 8.7;
const roll_left = -4.55;
const focal = 3.05;
// The roll's length, rolled up or unrolling.
const roll_length = 3.12;
struct Scene { view: mat4x4f, projection: mat4x4f };
struct Parameters { mode: f32, opened: f32, selected: f32, hovered: f32 };
struct Draw { model: mat4x4f, normal: mat4x4f, color: vec4f, settings: vec4f, parameters: Parameters };
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var paper: texture_2d<f32>;
@group(1) @binding(2) var paper_sampler: sampler;
struct Input { @location(0) position: vec3f, @location(1) normal: vec3f, @location(2) uv: vec2f };
struct Output { @builtin(position) position: vec4f, @location(0) uv: vec2f, @location(1) normal: vec3f, @location(2) local: vec2f, @location(3) edge: f32 };
// How far the plans still have to ride out: the sheet's free end leads, so
// everything on the paper travels with it as it unrolls.
fn travel(opened: f32) -> f32 { return (1.0-opened)*(roll_left+paper_length); }
@vertex fn vertex(v:Input)->Output {
  let p=draw.parameters;
  // The paper fed off the roll so far.
  let fed=paper_length*p.opened;
  var position=vec3f(0); var n=vec3f(0,0,1); var uv=v.uv; var edge=1.0;
  if(p.mode<.5) {
    let angle=v.uv.y*15.708-fed/.235;
    let radius=.22+v.uv.y*.025;
    let local=vec3f(sin(angle)*radius,(v.uv.x-.5)*roll_length,cos(angle)*radius);
    position=(draw.model*vec4f(local,1)).xyz;
    n=(draw.normal*vec4f(sin(angle),0,cos(angle),0)).xyz;
    // The texture travels at the strip's speed and meets it at the back
    // tangent. The cylinder's hidden seam falls underneath the emerging paper.
    let around=atan2(sin(angle),cos(angle));
    uv=vec2f((3.14159265-around)*.235*.16-fed*.16,v.uv.x);
  } else {
    let along=v.uv.x*fed;
    let join=1.4*p.opened;
    let q=clamp(along/join,0.0,1.0);
    let u=1.0-q;
    let roll_span=roll_length*.96*p.opened;
    let strip_span=2.7*p.opened;
    // Both draws share the same transform. Starting on the roll itself
    // follows its tilt exactly, so no gap can open above or below the join.
    let a=(draw.model*vec4f(0,(v.uv.y-.5)*roll_span,-.242,1)).xyz;
    let b=a+(draw.normal*vec4f(join*.5,0,0,0)).xyz;
    let d=vec3f(roll_left*p.opened+.15+join,(v.uv.y-.5)*strip_span,-.32);
    let c=d-vec3f(join*.4,0,0);
    let bend=u*u*u*a+3.0*u*u*q*b+3.0*u*q*q*c+q*q*q*d;
    let tangent=3.0*u*u*(b-a)+6.0*u*q*(c-b)+3.0*q*q*(d-c);
    let span=mix((draw.model*vec4f(0,roll_span,0,0)).xyz,vec3f(0,strip_span,0),smoothstep(0.0,1.0,q));
    let ripple=.015*sin((along-fed)*2.4)*pow(abs(v.uv.y-.5)*2.0,5.0);
    // The free end lifts in a slight curl, as paper does fresh off a roll.
    let left=fed-along;
    let lifting=max(0.0,1.0-left/.45);
    let curl=.1*lifting*lifting;
    position=bend+vec3f(max(0.0,along-join),0,ripple*smoothstep(0.0,1.0,q)+curl);
    n=normalize(cross(normalize(tangent)+vec3f(0,0,.2*lifting/.45),span));
    let attached_v=(v.uv.y-.5)*.96*p.opened+.5;
    uv=vec2f((along-fed)*.16,mix(attached_v,v.uv.y,smoothstep(0.0,1.0,q)));
    edge=min(min(v.uv.y,1.0-v.uv.y)*strip_span,left);
  }
  return Output(scene.projection*scene.view*vec4f(position,1),uv,n,position.xy,edge);
}
@fragment fn fragment(v:Output)->@location(0) vec4f {
  let tiled=1.0-abs(fract(v.uv*.5)*2.0-1.0);
  let pigment=textureSample(paper,paper_sampler,tiled).rgb;
  var color=pigment*vec3f(.72,.8,.91);
  if(draw.parameters.mode>.5) {
    // A white baseline under each plan: faint, clearer under the pointer and
    // bright under the building in hand.
    for(var i=0u;i<3u;i++) {
      let x=slot_first+f32(i)*slot_width-travel(draw.parameters.opened);
      let hovered=abs(draw.parameters.hovered-f32(i+1u))<.1;
      let selected=abs(draw.parameters.selected-f32(i+1u))<.1;
      let line=(1.0-smoothstep(.012,.026,abs(v.local.y+.98)))*(1.0-smoothstep(.68,.72,abs(v.local.x-x)));
      color=mix(color,vec3f(.94,.97,1),line*select(select(.13,.45,hovered),.94,selected));
    }
    color=mix(color,vec3f(.77,.84,.86),1.0-smoothstep(.008,.023,v.edge));
  }
  let lit=.6+.4*abs(normalize(v.normal).z);
  return vec4f(color*lit,1);
}

files.src/assets/brick_ghost.wgsl:
// Ghost salt bricks falling into the stash the hand's salt goes into if it
// lets go (src/salt.blot, `drop_draws`): pale salt tinted green, lit softly
// from the sun's side, glowing green at its edges and see-through, so it
// reads as a promise rather than salt lying there, and stands apart from the
// gold of the drop rays (drop_ray.wgsl) it falls through.
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
  zenith: vec4f,
  horizon: vec4f,
  ground: vec4f,
  eye: vec4f,
};
// How much of it shows, 0 to 1, and how brightly it flashes as it lands.
struct Parameters {
  fade: f32,
  flash: f32,
  unused0: f32,
  unused1: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;

// Its body, a little brighter than lit salt and tinted green, and the green
// light at its rim.
const salt = vec3f(1.05, 1.45, 1.05);
const green = vec3f(0.9, 2.4, 1.0);

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) normal: vec3f,
  @location(1) world: vec3f,
};

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let world = draw.model * vec4f(input.position, 1.0);
  output.position = scene.projection * scene.view * world;
  output.normal = (draw.normal * vec4f(input.normal, 0.0)).xyz;
  output.world = world.xyz;
  return output;
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let normal = normalize(input.normal);
  let eye = normalize(scene.eye.xyz - input.world);
  let sun = normalize(-scene.light_direction.xyz);
  // It glows the same by day and night, so it reads in the dark too: only a
  // little shading tells its faces apart, the top the brightest.
  let shade = 0.8 + 0.12 * max(dot(normal, sun), 0.0) + 0.08 * max(normal.y, 0.0);
  let rim = pow(1.0 - abs(dot(normal, eye)), 2.0);
  let flash = draw.parameters.flash;
  let color = mix(salt * shade, green, rim) * (1.0 + flash * 0.35) * draw.color.rgb;
  let alpha = min(0.9, 0.42 + rim * 0.45 + flash * 0.15) * draw.parameters.fade * draw.color.a;
  return vec4f(color, alpha);
}

files.src/assets/bubble.wgsl:
// A cartoon bubble, drawn whole from one sprite: a rounded box and its tail
// merged into one shape, so nothing joins them, in a thick ink outline round
// a flat cream fill, a little lighter toward the top, over a hard shadow
// dropped below it. The sprite's color tints the fill, so the same shape
// makes a menu's rows, lit or dimmed. It crumbles away: pieces break off from
// the edges inward, greyed with dust where they break, leaving nothing.
//
// The sprite's rectangle holds the whole bubble, the tail's tip at its bottom
// middle, a margin `4 * scale` all round; u1 is the tail's height, in pixels
// (0 for none, below 0 for a tail up from its top middle instead), and v1 the
// corners' radius.
//
// What the sprite passes (src/speech.blot): how far it has crumbled, 0 to 1;
// the screen's scale (pixels per pixel at 720 lines); and the crumbling's
// origin in pixels, which text over the bubble shares (text.wgsl).
struct Parameters {
  crumbled: f32,
  scale: f32,
  origin_x: f32,
  origin_y: f32,
};
struct Screen {
  size: vec4f,
};
struct Sprite {
  rect: vec4f,
  uv: vec4f,
  color: vec4f,
  parameters: vec4f,
};
@group(0) @binding(0) var<uniform> screen: Screen;
@group(0) @binding(1) var<storage, read> sprites: array<Sprite>;
@group(0) @binding(2) var image: texture_2d<f32>;
@group(0) @binding(3) var image_sampler: sampler;

struct Corner {
  @builtin(position) position: vec4f,
  // Pixels from the sprite's top left.
  @location(0) local: vec2f,
  @location(1) @interpolate(flat) size: vec2f,
  @location(2) @interpolate(flat) uv: vec4f,
  @location(3) @interpolate(flat) color: vec4f,
  @location(4) @interpolate(flat) parameters: vec4f,
};

@vertex fn vertex(@builtin(vertex_index) vertex: u32, @builtin(instance_index) index: u32) -> Corner {
  let sprite = sprites[index];
  let corner = array<vec2f, 6>(vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(0.0, 1.0), vec2f(0.0, 1.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0))[vertex];
  let pixel = sprite.rect.xy + corner * sprite.rect.zw;
  var output: Corner;
  output.position = vec4f(pixel.x / screen.size.x * 2.0 - 1.0, 1.0 - pixel.y / screen.size.y * 2.0, 0.0, 1.0);
  output.local = corner * sprite.rect.zw;
  output.size = sprite.rect.zw;
  output.uv = sprite.uv;
  output.color = sprite.color;
  output.parameters = sprite.parameters;
  return output;
}

// The crumbling's noise, the same as text.wgsl's.
fn hash(p: vec2f) -> f32 {
  var q = fract(vec3f(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}
fn smooth_noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2f(1.0, 0.0)), u.x),
    mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), u.x), u.y);
}
fn crumble_noise(pixel: vec2f, origin: vec2f, scale: f32) -> f32 {
  let p = (pixel - origin) / (max(scale, 0.001) * 14.0);
  return smooth_noise(p) * 0.5 + smooth_noise(p * 2.7 + 17.1) * 0.3 + hash(floor((pixel - origin) / max(scale * 1.5, 0.5))) * 0.2;
}

// Signed distances in pixels, negative inside.
fn rounded_box(p: vec2f, centre: vec2f, half: vec2f, radius: f32) -> f32 {
  let q = abs(p - centre) - (half - radius);
  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - radius;
}
fn triangle(p: vec2f, a: vec2f, b: vec2f, c: vec2f) -> f32 {
  let e0 = b - a;
  let e1 = c - b;
  let e2 = a - c;
  let v0 = p - a;
  let v1 = p - b;
  let v2 = p - c;
  let pq0 = v0 - e0 * clamp(dot(v0, e0) / dot(e0, e0), 0.0, 1.0);
  let pq1 = v1 - e1 * clamp(dot(v1, e1) / dot(e1, e1), 0.0, 1.0);
  let pq2 = v2 - e2 * clamp(dot(v2, e2) / dot(e2, e2), 0.0, 1.0);
  let s = sign(e0.x * e2.y - e0.y * e2.x);
  let d = min(min(vec2f(dot(pq0, pq0), s * (v0.x * e0.y - v0.y * e0.x)),
    vec2f(dot(pq1, pq1), s * (v1.x * e1.y - v1.y * e1.x))),
    vec2f(dot(pq2, pq2), s * (v2.x * e2.y - v2.y * e2.x)));
  return -sqrt(d.x) * sign(d.y);
}
fn smooth_union(a: f32, b: f32, k: f32) -> f32 {
  let h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

// The bubble's distance at `p` in a sprite `size` big, its tail down (or,
// for a `tail` below 0, up).
fn bubble(p: vec2f, size: vec2f, scale: f32, tail: f32, radius: f32) -> f32 {
  let margin = 4.0 * scale;
  let up = tail < 0.0;
  let length = abs(tail);
  // Laid out tail down: a tail up is the same, upside down.
  let q = select(p, vec2f(p.x, size.y - p.y), up);
  let low = vec2f(margin);
  let high = vec2f(size.x - margin, size.y - margin - length);
  let body = rounded_box(q, (low + high) * 0.5, (high - low) * 0.5, min(radius, (high.y - low.y) * 0.5));
  if (length <= 0.0) {
    return body;
  }
  let middle = size.x * 0.5;
  // The tail leans a little, its base sunk into the body so they merge.
  let base = high.y - 4.0 * scale;
  let point = triangle(q,
    vec2f(middle - 9.0 * scale, base),
    vec2f(middle + 7.0 * scale, base),
    vec2f(middle - 3.0 * scale, size.y - margin));
  return smooth_union(body, point, 5.0 * scale);
}

const ink = vec3f(0.11, 0.09, 0.12);
const cream = vec3f(1.0, 0.975, 0.92);
const dust = vec3f(0.62, 0.6, 0.58);

// The sprite's parameters by name.
fn named(v: vec4f) -> Parameters {
  return Parameters(v.x, v.y, v.z, v.w);
}

@fragment fn fragment(corner: Corner) -> @location(0) vec4f {
  let p = named(corner.parameters);
  let scale = max(p.scale, 0.001);
  let shape = bubble(corner.local, corner.size, scale, corner.uv.z, corner.uv.w);
  // The shadow, dropped straight down, as a cartoon's.
  let shadow = bubble(corner.local - vec2f(0.0, 3.5) * scale, corner.size, scale, corner.uv.z, corner.uv.w);
  let aa = max(fwidth(shape), 0.35);
  let noise = crumble_noise(corner.position.xy, vec2f(p.origin_x, p.origin_y), scale);

  let ink_width = 3.0 * scale;
  let covered = 1.0 - smoothstep(-aa, aa, shape);
  let filled = 1.0 - smoothstep(-ink_width - aa, -ink_width + aa, shape);
  // Flat, a little lighter toward the top, and a little darker just inside
  // the outline at the bottom, as a cartoon shades it.
  let down = corner.local.y / max(corner.size.y, 1.0);
  let fill = cream * corner.color.rgb * mix(1.03, 0.94, smoothstep(0.2, 1.0, down));
  var color = mix(ink, fill, filled);
  var alpha = covered;
  var shade = (1.0 - smoothstep(-aa, aa, shadow)) * 0.3 * (1.0 - covered);

  let crumbled = p.crumbled;
  if (crumbled > 0.0) {
    // The edges go first.
    let left = noise - 0.22 * smoothstep(-25.0 * scale, 0.0, shape) - (crumbled * 1.25 - 0.1);
    color = mix(color, dust, smoothstep(0.07, 0.0, left) * 0.8);
    let kept = step(0.0, left);
    alpha *= kept;
    shade *= kept;
  }
  // The bubble over its shadow.
  let total = alpha + shade;
  return vec4f(color * alpha / max(total, 0.0001), total * corner.color.a);
}

files.src/assets/building_stage.wgsl:
struct Scene {
  view: mat4x4f, projection: mat4x4f, ambient: vec4f,
  light_direction: vec4f, light_color: vec4f, light_view_projection: mat4x4f,
  shadow: vec4f, zenith: vec4f, horizon: vec4f, ground: vec4f, eye: vec4f,
};
struct Parameters { height: f32, ghost: f32, blocked: f32, unused: f32 };
struct Draw { model: mat4x4f, normal: mat4x4f, color: vec4f, settings: vec4f, parameters: Parameters };
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var palette: texture_2d<f32>;
@group(1) @binding(2) var surface_sampler: sampler;
struct Input { @location(0) position: vec3f, @location(1) normal: vec3f, @location(2) uv: vec2f };
struct Output { @builtin(position) position: vec4f, @location(0) normal: vec3f, @location(1) uv: vec2f, @location(2) world: vec3f };
@vertex fn vertex(v:Input)->Output {
  var p=v.position; p.y=min(p.y,draw.parameters.height);
  let n=select(v.normal,vec3f(0,1,0),v.position.y>draw.parameters.height);
  let world=draw.model*vec4f(p,1);
  return Output(scene.projection*scene.view*world,(draw.normal*vec4f(n,0)).xyz,v.uv,world.xyz);
}
@fragment fn fragment(v:Output)->@location(0) vec4f {
  let normal=normalize(v.normal);
  if(draw.parameters.ghost>.5) {
    let rim=pow(1.0-abs(dot(normal,normalize(scene.eye.xyz-v.world))),2.0);
    let tint=select(vec3f(.44,.77,1),vec3f(1,.29,.23),draw.parameters.blocked>.5);
    let stone=textureSample(palette,surface_sampler,v.uv).rgb;
    let light=.55+.45*max(dot(normal,normalize(-scene.light_direction.xyz)),0.0);
    let color=tint*(vec3f(.4)+stone*.6)*light+vec3f(rim*.15);
    return vec4f(color,.32+rim*.28);
  }
  let albedo=textureSample(palette,surface_sampler,v.uv).rgb;
  let light=max(dot(normal,normalize(-scene.light_direction.xyz)),0.0);
  var shadow=1.0;
  if(scene.shadow.x>.5) {
    let clip=scene.light_view_projection*vec4f(v.world+normal*scene.shadow.z,1);
    let ndc=clip.xyz/clip.w; let uv=vec2f(ndc.x*.5+.5,.5-ndc.y*.5);
    if(all(uv>=vec2f(0))&&all(uv<=vec2f(1))&&ndc.z<1.0) {
      shadow=textureSampleCompareLevel(shadow_map,shadow_sampler,uv,ndc.z-.0004);
    }
  }
  return vec4f(albedo*(scene.ambient.rgb+scene.light_color.rgb*(light*.85+.15)*shadow),1);
}

files.src/assets/construction_bar.wgsl:
struct Parameters { progress: f32, scale: f32, unused0: f32, unused1: f32 };
struct Screen { size: vec4f };
struct Sprite { rect: vec4f, uv: vec4f, color: vec4f, parameters: vec4f };
@group(0) @binding(0) var<uniform> screen: Screen;
@group(0) @binding(1) var<storage,read> sprites: array<Sprite>;
struct Output { @builtin(position) position: vec4f, @location(0) local: vec2f, @location(1) @interpolate(flat) size: vec2f, @location(2) @interpolate(flat) parameters: vec4f };
@vertex fn vertex(@builtin(vertex_index) v:u32,@builtin(instance_index) i:u32)->Output {
  let s=sprites[i]; let c=array<vec2f,6>(vec2f(0,0),vec2f(1,0),vec2f(0,1),vec2f(0,1),vec2f(1,0),vec2f(1,1))[v];
  let p=s.rect.xy+c*s.rect.zw;
  return Output(vec4f(p.x/screen.size.x*2-1,1-p.y/screen.size.y*2,0,1),c*s.rect.zw,s.rect.zw,s.parameters);
}
fn box(p:vec2f,h:vec2f,r:f32)->f32 { let q=abs(p)-h+r; return length(max(q,vec2f(0)))+min(max(q.x,q.y),0.0)-r; }
@fragment fn fragment(v:Output)->@location(0) vec4f {
  let s=max(.5,v.parameters.y); let p=v.local-v.size*.5;
  let d=box(p,v.size*.5-vec2f(1),v.size.y*.5-1);
  let outer=1.0-smoothstep(-.7,.7,d);
  let border=smoothstep(-2.0*s-.6,-2.0*s+.6,d);
  let inset=3.5*s;
  let fill_width=max(0.0,(v.size.x-2*inset)*v.parameters.x);
  let left=-v.size.x*.5+inset;
  let fill=box(p-vec2f(left+fill_width*.5,0),vec2f(fill_width*.5,max(.1,v.size.y*.5-inset)),max(.1,v.size.y*.5-inset));
  let white=max(border,(1.0-smoothstep(-.5,.5,fill))*select(0.0,1.0,fill_width>1.0));
  return vec4f(vec3f(white),outer);
}

files.src/assets/crater.wgsl:
// The crater's wall round the arena (models/crater), in photographed rock
// and ground (models/textures/crater.py). Cliffs and steep faces are
// weathered rock, laid on from all three sides; gentler slopes and tops are
// grass among stones and earth, laid from above; they meet along the stones'
// edges, by height. Each is laid at two sizes, so neither repeats, and each
// peak takes a tone of its own. It casts shadows and takes them. Its peaks are too far out for the
// shadow map, so their form comes from the light itself: plain Lambert, the
// faces turned from the sun in shade, and the two values models/crater bakes
// into each vertex: how much of the sky it sees, which darkens gullies, the
// feet of cliffs and the valleys between peaks, and how far it stands proud
// of the ground round it, pale on ridges and dark in hollows.
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
  // The sky the scene sits under (the frame's): its colors overhead, at the
  // horizon and below it; and where the eye is.
  zenith: vec4f,
  horizon: vec4f,
  ground: vec4f,
  eye: vec4f,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  settings: vec4f,
  parameters: vec4f,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;
// The crater's textures (models/textures/crater.py): the rock's color and
// height, its normal and the ground's, and the ground's color and height.
@group(1) @binding(1) var rock_map: texture_2d<f32>;
@group(1) @binding(2) var surface_sampler: sampler;
@group(1) @binding(3) var normal_map: texture_2d<f32>;
@group(1) @binding(4) var ground_map: texture_2d<f32>;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  // x: how much of the sky it sees, 0 to 1; y: how far it stands proud of
  // the ground round it, in units.
  @location(8) baked: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) world: vec3f,
  @location(1) normal: vec3f,
  @location(2) baked: vec2f,
};

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let world = draw.model * vec4f(input.position, 1.0);
  output.position = scene.projection * scene.view * world;
  output.world = world.xyz;
  output.normal = normalize((draw.normal * vec4f(input.normal, 0.0)).xyz);
  output.baked = input.baked;
  return output;
}

// How much sunlight reaches `world`, as in scene.wgsl.
fn sunlit(world: vec3f, normal: vec3f) -> f32 {
  if (scene.shadow.x < 0.5) {
    return 1.0;
  }
  let clip = scene.light_view_projection * vec4f(world + normal * scene.shadow.z, 1.0);
  let ndc = clip.xyz / clip.w;
  let uv = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
  if (any(uv < vec2f(0.0)) || any(uv > vec2f(1.0)) || ndc.z > 1.0) {
    return 1.0;
  }
  var light = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      light += textureSampleCompareLevel(shadow_map, shadow_sampler,
        uv + vec2f(f32(x), f32(y)) * scene.shadow.y, ndc.z - 0.0004);
    }
  }
  return light / 9.0;
}

fn random(cell: vec3f, seed: u32) -> f32 {
  let c = vec3u(vec3i(cell));
  var h = (c.x * 0x8da6b343u) ^ (c.y * 0xd8163841u) ^ (c.z * 0xcb1ab31fu) ^ (seed * 0x9e3779b9u);
  h ^= h >> 16u;
  h *= 0x7feb352du;
  h ^= h >> 15u;
  h *= 0x846ca68bu;
  h ^= h >> 16u;
  return f32(h >> 8u) / 16777216.0;
}
fn noise(p: vec3f, seed: u32) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(random(i, seed), random(i + vec3f(1.0, 0.0, 0.0), seed), u.x);
  let b = mix(random(i + vec3f(0.0, 1.0, 0.0), seed), random(i + vec3f(1.0, 1.0, 0.0), seed), u.x);
  let c = mix(random(i + vec3f(0.0, 0.0, 1.0), seed), random(i + vec3f(1.0, 0.0, 1.0), seed), u.x);
  let d = mix(random(i + vec3f(0.0, 1.0, 1.0), seed), random(i + vec3f(1.0, 1.0, 1.0), seed), u.x);
  return mix(mix(a, b, u.y), mix(c, d, u.y), u.z);
}
fn fbm(p: vec3f, seed: u32) -> f32 {
  var sum = 0.0;
  var weight = 0.5;
  var q = p;
  for (var octave = 0u; octave < 3u; octave++) {
    sum += weight * noise(q, seed + octave * 5u);
    q = q * 2.07 + vec3f(3.1, -1.7, 2.3);
    weight *= 0.5;
  }
  return sum / 0.875;
}

// How wide a tile of each texture lies, in units, and how much their relief
// turns the light.
const rock_tile = 6.0;
const rock_wide = 29.0;
const ground_tile = 14.0;
const ground_wide_tile = 73.0;
const relief = 0.9;

// How squarely a surface facing `normal` faces each axis, summing to 1, sharp
// so the three projections of a texture meet in narrow seams.
fn facings(normal: vec3f) -> vec3f {
  let w = pow(abs(normal), vec3f(4.0));
  return w / (w.x + w.y + w.z);
}

// The rock texture laid on from all three sides (triplanar), a tile `tile`
// wide: its color and height, and how its relief turns the normal, in the
// world.
struct Surface {
  color: vec4f,
  bend: vec3f,
};
fn rock_on(p: vec3f, weights: vec3f, tile: f32) -> Surface {
  let ux = p.zy / tile;
  let uy = p.xz / tile;
  let uz = p.xy / tile;
  let nx = textureSample(normal_map, surface_sampler, ux).rg * 2.0 - 1.0;
  let ny = textureSample(normal_map, surface_sampler, uy).rg * 2.0 - 1.0;
  let nz = textureSample(normal_map, surface_sampler, uz).rg * 2.0 - 1.0;
  var surface: Surface;
  surface.color = textureSample(rock_map, surface_sampler, ux) * weights.x +
    textureSample(rock_map, surface_sampler, uy) * weights.y +
    textureSample(rock_map, surface_sampler, uz) * weights.z;
  surface.bend = vec3f(0.0, nx.y, nx.x) * weights.x + vec3f(ny.x, 0.0, ny.y) * weights.y +
    vec3f(nz.x, nz.y, 0.0) * weights.z;
  return surface;
}

// Light from all round as a surface facing `normal` takes it: the sky's,
// more from above and tinted by it, and a little bounced off the ground.
fn hemisphere(normal: vec3f) -> vec3f {
  let sky_tint = mix(vec3f(1.0), hue(scene.zenith.rgb), 0.25);
  let ground_tint = mix(vec3f(1.0), hue(scene.ground.rgb), 0.4);
  return scene.ambient.xyz * mix(ground_tint * 0.6, sky_tint * 1.05, normal.y * 0.5 + 0.5);
}

// A color's hue at the brightness of white, or white for black.
fn hue(color: vec3f) -> vec3f {
  let luma = dot(color, vec3f(0.299, 0.587, 0.114));
  return select(vec3f(1.0), color / max(luma, 0.001), luma > 0.001);
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let p = input.world;
  let normal = normalize(input.normal);
  // 0 level, 1 sheer.
  let steep = 1.0 - normal.y;
  let mottle = fbm(p * 0.35, 3u);
  // Rock up close and, mixed in, five times as wide, so neither repeats; and
  // the ground, a wide tile too, to break up its own.
  let weights = facings(normal);
  let near = rock_on(p, weights, rock_tile);
  let wide = rock_on(p, weights, rock_wide);
  let ground_uv = p.xz / ground_tile;
  let ground = textureSample(ground_map, surface_sampler, ground_uv);
  let ground_bend = textureSample(normal_map, surface_sampler, ground_uv).ba * 2.0 - 1.0;
  let ground_wide = textureSample(ground_map, surface_sampler, p.xz / ground_wide_tile).rgb;
  // Rock where it is steep, ground where it is not, meeting along the stones'
  // edges: whichever stands higher there, its height lifted where its side
  // of the slope is.
  let rocky = smoothstep(0.24, 0.5, steep + (mottle - 0.5) * 0.3);
  let rock_height = mix(near.color.a, wide.color.a, 0.4) + rocky * 1.2;
  let ground_height = ground.a + (1.0 - rocky) * 1.2;
  let top = max(rock_height, ground_height) - 0.25;
  let rock_part = max(rock_height - top, 0.0);
  let ground_part = max(ground_height - top, 0.0);
  let share = rock_part / max(rock_part + ground_part, 0.0001);
  let luma = vec3f(0.299, 0.587, 0.114);
  let rock = near.color.rgb * (0.55 + 0.9 * dot(wide.color.rgb, luma));
  let soil = ground.rgb * (0.55 + 0.9 * dot(ground_wide, luma));
  var albedo = mix(soil, rock, share);
  // Each peak a tone of its own.
  albedo *= 0.84 + 0.32 * fbm(p * 0.02 + vec3f(7.0, 0.0, 3.0), 23u);
  // Darker low down at the foot, where the floor meets it.
  albedo *= 0.75 + 0.25 * smoothstep(0.0, 2.5, p.y);
  // Ridges weather pale; hollows gather dust and shade.
  let open = clamp(input.baked.x, 0.0, 1.0);
  let proud = clamp(input.baked.y / 3.0, -1.0, 1.0);
  albedo *= 1.0 + 0.2 * proud;
  // The textures' relief turns the light.
  let bend = mix(vec3f(ground_bend.x, 0.0, ground_bend.y), mix(near.bend, wide.bend, 0.3), share);
  let shaded = normalize(normal + bend * relief);

  if (draw.settings.x < 0.5) {
    return vec4f(albedo, 1.0);
  }
  let to_light = normalize(-scene.light_direction.xyz);
  let sun = sunlit(p, normal);
  let diffuse = max(dot(shaded, to_light), 0.0);
  let ambient = hemisphere(shaded) * mix(0.3, 1.0, open);
  let direct = scene.light_color.xyz * diffuse * sun * mix(0.55, 1.0, open);
  return vec4f(albedo * (ambient + direct), 1.0);
}

files.src/assets/crystal.wgsl:
// The rose salt crystals that grow on the gnorp rock (src/crystals.blot,
// models/crystals/crystals.py), as glass: mostly solid rose, a little of what
// is behind showing through, the sky mirrored in their faces and more so as
// they turn away (Fresnel), each flat facet flashing sharply in the sun, and
// lit from within where the sun shines through them. Glass splits light by
// its colour (chromatic aberration, dispersion): its flashes and the light
// through it bend a little differently for red, green and blue, so they come
// apart in rainbow fringes, and its edges shimmer through the spectrum. The
// material blends over the scene behind.
//
// So they catch the eye, their colors shiver a little, all the time: under
// each, a faint red ghost and a blue one sit a pixel or so off to either side,
// jittering (src/crystals.blot draws them first, then the crystal over them).
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
};
// What src/crystals.blot passes each draw: the time in seconds, which ghost
// it is (-1 the red, 1 the blue, 0 the crystal itself), and a seed of the
// crystal's own, so each shakes its own way.
struct Parameters {
  seconds: f32,
  ghost: f32,
  seed: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  // x: lit.
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) normal: vec3f,
  @location(1) world: vec3f,
  // How far up the crystal, 0 at its foot, for a deeper tint low down.
  @location(2) up: f32,
};

fn hash(n: f32) -> f32 {
  return fract(sin(n * 12.9898) * 43758.5453);
}

// How far a ghost stands off, in screen heights (two to a side): about a
// pixel, jittering twelve times a second.
fn shake(seconds: f32, seed: f32) -> vec2f {
  let tick = floor(seconds * 12.0) + seed * 17.0;
  let jitter = vec2f(hash(tick) - 0.5, hash(tick + 3.7) - 0.5) * 0.005;
  let split = vec2f(0.0025, 0.0) + jitter;
  // As far across as up, whatever the screen's shape.
  return vec2f(split.x * scene.projection[0][0] / scene.projection[1][1], split.y);
}

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let world = draw.model * vec4f(input.position, 1.0);
  output.position = scene.projection * scene.view * world;
  let ghost = draw.parameters.ghost;
  if (ghost != 0.0) {
    let off = shake(draw.parameters.seconds, draw.parameters.seed) * ghost * output.position.w;
    output.position = vec4f(output.position.xy + off, output.position.zw);
  }
  output.normal = (draw.normal * vec4f(input.normal, 0.0)).xyz;
  output.world = world.xyz;
  output.up = clamp(input.position.y / 1.3, 0.0, 1.0);
  return output;
}

// How much sunlight reaches `world`, as in scene.wgsl.
fn sunlit(world: vec3f, normal: vec3f) -> f32 {
  if (scene.shadow.x < 0.5) {
    return 1.0;
  }
  let clip = scene.light_view_projection * vec4f(world + normal * scene.shadow.z, 1.0);
  let ndc = clip.xyz / clip.w;
  let uv = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
  if (any(uv < vec2f(0.0)) || any(uv > vec2f(1.0)) || ndc.z > 1.0) {
    return 1.0;
  }
  var light = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      light += textureSampleCompareLevel(shadow_map, shadow_sampler,
        uv + vec2f(f32(x), f32(y)) * scene.shadow.y, ndc.z - 0.0004);
    }
  }
  return light / 9.0;
}

// Rose salt glass, deeper toward the foot.
const rose = vec3f(1.0, 0.62, 0.72);
const deep_rose = vec3f(0.78, 0.3, 0.44);

// The sky the faces mirror, from the scene's own light: its ambient color,
// brighter overhead, paler toward the horizon.
fn sky(direction: vec3f) -> vec3f {
  // Contrasty, as cut glass shows it: a bright band round the horizon, a lit
  // sky over it and the dark ground below, so a facet swings from bright to
  // dark as it turns.
  let up = clamp(direction.y, -1.0, 1.0);
  let band = exp(-pow(up / 0.18, 2.0)) * 1.4;
  let zenith = scene.ambient.xyz * 1.6 + scene.light_color.xyz * 0.45;
  let ground = scene.ambient.xyz * 0.25;
  return select(ground, zenith * (0.6 + 0.4 * up), up >= 0.0) + vec3f(1.0, 0.98, 0.95) * band * (scene.ambient.xyz + vec3f(0.35));
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let n = normalize(input.normal);
  let tint = mix(deep_rose, rose, smoothstep(0.0, 0.8, input.up));
  if (draw.settings.x < 0.5) {
    return vec4f(tint, 0.7);
  }
  let rotation = mat3x3f(scene.view[0].xyz, scene.view[1].xyz, scene.view[2].xyz);
  let eye = -(transpose(rotation) * scene.view[3].xyz);
  let to_eye = normalize(eye - input.world);
  let to_light = normalize(-scene.light_direction.xyz);
  let sun = sunlit(input.world, n);
  let facing = max(dot(n, to_eye), 0.0);
  // Glass reflects little head on and nearly all at a grazing angle.
  let fresnel = 0.12 + 0.88 * pow(1.0 - facing, 4.0);
  // Each colour sees the facet a little turned: red one way, blue the other,
  // across the line to the eye.
  let across = normalize(to_eye - n * facing + vec3f(0.0001, 0.0002, 0.0));
  let bent = array<vec3f, 3>(normalize(n - across * 0.07), n, normalize(n + across * 0.07));
  // How far each colour bends going in (its index of refraction).
  let bends = array<f32, 3>(0.665, 0.65, 0.635);
  var flash = vec3f(0.0);
  var fire = vec3f(0.0);
  for (var c = 0; c < 3; c++) {
    // The sun in the facet: a sharp flash, and a softer sheen round it.
    let toward_sun = max(dot(reflect(-to_eye, bent[c]), to_light), 0.0);
    flash[c] = pow(toward_sun, 500.0) * 14.0 + pow(toward_sun, 24.0) * 0.9;
    // The sun seen through it, bent in.
    let inside = refract(-to_eye, n, bends[c]);
    fire[c] = pow(max(dot(inside, to_light), 0.0), 12.0) * 2.2;
  }
  flash *= sun;
  var reflected = sky(reflect(-to_eye, n)) + scene.light_color.xyz * flash;
  // The body: rose, the light through it brightest where the sun comes in
  // behind it, its fire split in colours, a little ambient caught inside.
  let through = pow(max(dot(-to_eye, to_light), 0.0), 3.0);
  let body = tint * (scene.ambient.xyz * 0.9 + scene.light_color.xyz * (0.3 + 0.4 * max(dot(n, to_light), 0.0) + 0.8 * through) * mix(sun, 1.0, 0.5)) +
    scene.light_color.xyz * fire * mix(sun, 1.0, 0.4) * 0.6;
  // Its edges shimmer through the spectrum as they turn away.
  let turned = 1.0 - facing;
  let spectrum = 0.5 + 0.5 * cos(6.2831853 * (vec3f(0.0, 0.33, 0.67) + turned * 2.2));
  reflected = mix(reflected, reflected * spectrum * 1.4, smoothstep(0.35, 0.9, turned) * 0.5);
  let color = mix(body, reflected, fresnel) + scene.light_color.xyz * flash * (1.0 - fresnel) * 0.6;
  // Mostly solid; a little of what is behind shows through head on.
  let alpha = clamp(mix(0.8, 0.98, fresnel) + max(flash.r, max(flash.g, flash.b)) * 0.3, 0.0, 1.0);
  // A ghost keeps only its own end of the spectrum, and shows less.
  let ghost = draw.parameters.ghost;
  if (ghost < -0.5) {
    return vec4f(color.r * 1.15 + 0.15, 0.0, 0.0, alpha * 0.45);
  }
  if (ghost > 0.5) {
    return vec4f(0.0, color.g * 0.35, color.b * 1.15 + 0.2, alpha * 0.45);
  }
  return vec4f(color, alpha);
}

files.src/assets/drop_ray.wgsl:
// Warm beams of light shooting down at salt drop spots (src/salt.blot,
// `beam_draw`). Each is a bounded volume, a box leaning as its draw turns it,
// that integrates soft light along the view ray, so it stays round as the
// camera rotates. Its geometry never scales with the animation or collapses
// to zero; only its light shifts, and pulses of it run down toward the spot.
const height = 64.0;

struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
  zenith: vec4f,
  horizon: vec4f,
  ground: vec4f,
  eye: vec4f,
};
// The game's seconds, how strong it shines, and a phase setting each beam's
// ribbons, pulses and breathing apart from its neighbours'.
struct Parameters {
  seconds: f32,
  strength: f32,
  phase: f32,
  unused0: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) local: vec3f,
};
// The box spans -1..1 along its draw's turned, scaled axes, its foot the
// middle of its bottom face, the beam running up its y.
fn world_point(point: vec3f) -> vec3f {
  return (draw.model * vec4f(point, 1.0)).xyz;
}
fn local_eye() -> vec3f {
  let offset = scene.eye.xyz - draw.model[3].xyz;
  let x = draw.model[0].xyz;
  let y = draw.model[1].xyz;
  let z = draw.model[2].xyz;
  return vec3f(dot(offset, x) / dot(x, x), dot(offset, y) / dot(y, y), dot(offset, z) / dot(z, z));
}
@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  // Show the inside of the same shell when the camera enters the beam.
  let inside = all(abs(local_eye()) < vec3f(1.0));
  output.local = input.position * vec3f(select(1.0, -1.0, inside), 1.0, 1.0);
  output.position = scene.projection * scene.view * vec4f(world_point(output.local), 1.0);
  return output;
}

fn density(point: vec3f) -> f32 {
  let up = clamp(point.y * 0.5 + 0.5, 0.0, 1.0);
  let radius = mix(0.48, 0.78, up);
  let radial = length(point.xz) / radius;
  let edge = exp(-3.6 * radial * radial) * (1.0 - smoothstep(0.72, 1.0, radial));
  // Slow, uneven ribbons give the shaft texture without discrete particles,
  // and brighter pulses run down it toward the spot.
  let time = draw.parameters.seconds;
  let phase = draw.parameters.phase;
  let ribbons = 0.76 + 0.14 * sin(point.x * 31.0 + phase + sin(point.z * 11.0 + time * 0.17))
    + 0.10 * sin(point.z * 43.0 + point.x * 17.0 - time * 0.13 + phase);
  let pulses = 0.8 + 0.2 * sin(point.y * 70.0 + time * 6.0 + phase * 3.0);
  let sky_fade = 1.0 - smoothstep(0.55, 1.0, up);
  // A soft pool where the beam meets the floor anchors the drop spot, faint
  // enough that the ghost bricks falling there show through all the beams'
  // light (src/salt.blot, `drop_draws`); the beam fades out just above the
  // floor, its foot sunk just below it.
  let above = world_point(point).y;
  let pool = 0.08 * exp(-max(above, 0.0) * 1.5);
  let above_ground = smoothstep(0.0, 0.6, above);
  return edge * (0.22 * ribbons * pulses * sky_fade + pool) * above_ground;
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let eye = local_eye();
  let direction = normalize(input.local - eye);
  let safe_direction = select(vec3f(-1.0), vec3f(1.0), direction >= vec3f(0.0))
    * max(abs(direction), vec3f(0.00001));
  let first = (-vec3f(1.0) - eye) / safe_direction;
  let last = (vec3f(1.0) - eye) / safe_direction;
  let near = min(first, last);
  let far = max(first, last);
  let start = max(max(near.x, near.y), max(near.z, 0.0));
  let end = min(min(far.x, far.y), far.z);
  let step = max(end - start, 0.0) / 16.0;
  let world_step = length((draw.model * vec4f(direction * step, 0.0)).xyz);
  var light = 0.0;
  for (var i = 0; i < 16; i++) {
    light += density(eye + direction * (start + (f32(i) + 0.5) * step)) * world_step;
  }
  let breath = 0.88 + 0.12 * sin(draw.parameters.seconds * 0.9 + draw.parameters.phase);
  let alpha = (1.0 - exp(-light * breath * draw.parameters.strength)) * 0.9;
  return vec4f(vec3f(2.4, 2.1, 1.5) * draw.color.rgb, alpha * draw.color.a);
}

files.src/assets/dust.wgsl:
// The dust a building blasts out as it lands (models/dust/dust.py): puffs
// that face the camera and shoot out from the building's foot in a ring, as
// the foot of a mushroom cloud does, very fast at first, then all but
// stopping, curling up and swelling as they slow, while a few rise in the
// middle; they thin away within the second.
// Each vertex carries its puff's corner (uv, -1..1), the way it rolls out
// and how high (position: x and z, y), three random values of its own
// (normal) and whether it rises in the middle (attributes.x) with one more
// (attributes.y).
//
// The same puffs glitter when a salt crystal bursts (src/crystals.blot):
// thrown out every way from where it was, small and white, sparkling.
//
// The draw's model matrix places the burst at the building's foot (or where
// the crystal was).
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
};
// What a draw passes: the seconds since the burst went up, the building's
// radius, and 1 for a crystal's glitter (src/buildings.blot,
// src/crystals.blot).
struct Parameters {
  age: f32,
  radius: f32,
  glitter: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  // x: lit.
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
  @location(8) attributes: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) corner: vec2f,
  // How thick the puff is, 0..1, and its own random value.
  @location(1) thickness: f32,
  @location(2) seed: f32,
  // The camera's right and up, to light the puff as a ball.
  @location(3) right: vec3f,
  @location(4) up: vec3f,
  // How high over the floor, to fade into it.
  @location(5) height: f32,
  @location(6) tint: f32,
  @location(7) glitter: f32,
};

// How long the burst lasts, in seconds.
const lasts = 0.9;

// Most of the way in the first tenth of the time.
fn blast(t: f32) -> f32 {
  let u = 1.0 - t;
  return 1.0 - u * u * u * u * u * u;
}

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  let t = clamp(draw.parameters.age / lasts, 0.0, 1.0);
  let radius = max(draw.parameters.radius, 0.3);
  let seeds = input.normal;
  let middle = input.attributes.x > 0.5;
  let rolled = blast(t);
  let way = vec2f(input.position.x, input.position.z);
  // The ring rolls out from under the building's edge, the puffs at their
  // own pace; it curls up as it slows. Those in the middle rise, spreading a
  // little.
  var out = radius * (0.75 + (1.1 + 1.5 * seeds.x) * rolled);
  var height = radius * (0.16 + (0.1 + 0.35 * input.position.y) * rolled + 0.5 * t * input.position.y);
  var size = radius * (0.38 + (0.3 + 0.35 * seeds.y) * rolled);
  if (middle) {
    out = radius * (0.25 + 0.7 * seeds.x) * (0.4 + 0.6 * rolled);
    height = radius * (0.3 + (0.9 + 1.2 * seeds.z) * rolled);
    size = radius * (0.35 + (0.2 + 0.3 * seeds.y) * rolled);
  }
  // A little sideways drift round the ring, so the puffs do not run in
  // straight lines.
  let across = vec2f(-way.y, way.x) * (seeds.z - 0.5) * radius * 0.5 * rolled;
  var centre = draw.model[3].xyz + vec3f(way.x * out + across.x, height, way.y * out + across.y);
  // A crystal's glitter flies out every way, and falls a little.
  let glittering = draw.parameters.glitter > 0.5;
  if (glittering) {
    let flung = normalize(vec3f(way.x, (input.position.y - 0.45) * 2.2, way.y));
    centre = draw.model[3].xyz + flung * radius * (0.2 + (1.2 + 1.6 * seeds.x) * rolled) - vec3f(0.0, 0.6 * t * t, 0.0);
    size = radius * (0.12 + 0.16 * seeds.y) * (1.0 - 0.5 * t);
  }
  let right = vec3f(scene.view[0].x, scene.view[1].x, scene.view[2].x);
  let up = vec3f(scene.view[0].y, scene.view[1].y, scene.view[2].y);
  // Each puff turns slowly as it rolls.
  let spin = (seeds.y - 0.5) * 2.0 * t + seeds.z * 6.2831853;
  let c = cos(spin);
  let s = sin(spin);
  let turned = vec2f(input.uv.x * c - input.uv.y * s, input.uv.x * s + input.uv.y * c);
  let world = centre + (right * turned.x + up * turned.y) * size;

  var output: VertexOutput;
  output.position = scene.projection * scene.view * vec4f(world, 1.0);
  output.corner = input.uv;
  // Thick at once, then thinning away, the ring's outer puffs first.
  let fading = 1.0 - smoothstep(0.1 + 0.25 * (1.0 - seeds.x), 1.0, t);
  output.thickness = smoothstep(0.0, 0.02, t) * fading * select(0.85, 0.6, middle);
  output.seed = input.attributes.y;
  output.right = right;
  output.up = up;
  output.height = select(world.y, 1.0, glittering);
  output.glitter = select(0.0, 1.0, glittering);
  // The low, thick dust is earthier, what rises paler.
  output.tint = clamp(input.position.y * 0.7 + seeds.z * 0.3, 0.0, 1.0);
  return output;
}

fn hash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(12.9898, 78.233))) * 43758.5453);
}
fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2f(1.0, 0.0)), u.x), mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), u.x), u.y);
}

// Dusty earth, and the paler salt dust over it.
const earth = vec3f(0.6, 0.53, 0.45);
const pale = vec3f(0.88, 0.85, 0.79);

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  // A soft, lumpy ball.
  let p = input.corner;
  let lumps = noise(p * 2.3 + input.seed * 37.0) * 0.6 + noise(p * 5.1 + input.seed * 11.0) * 0.4;
  let d = length(p) + (lumps - 0.5) * 0.45;
  let body = 1.0 - smoothstep(0.35, 1.0, d);
  let alpha = body * input.thickness * (0.7 + 0.3 * lumps) * smoothstep(0.0, 0.35, input.height);
  if (alpha < 0.004) {
    discard;
  }
  // Lit as a ball would be: its surface's way out from the camera's view.
  let z = sqrt(max(1.0 - dot(p, p), 0.0));
  let toward = normalize(cross(input.right, input.up));
  let surface = normalize(input.right * p.x + input.up * p.y + toward * z);
  let to_light = normalize(-scene.light_direction.xyz);
  let lit = scene.ambient.xyz * 1.3 + scene.light_color.xyz * (0.35 + 0.65 * max(dot(surface, to_light), 0.0));
  let dust = mix(earth, pale, clamp(input.tint + p.y * 0.25 + (lumps - 0.5) * 0.4, 0.0, 1.0));
  var color = select(dust, dust * lit, draw.settings.x > 0.5) * (0.88 + 0.24 * lumps);
  if (input.glitter > 0.5) {
    // Salt white, catching the light: bright and flickering, each its own.
    let sparkle = step(0.6, fract(input.seed * 37.0 + draw.parameters.age * 9.0));
    color = vec3f(1.0, 0.99, 0.96) * (0.9 + 0.8 * sparkle);
    return vec4f(color, min(alpha * 1.6, 1.0));
  }
  return vec4f(color, alpha);
}

files.src/assets/earth.wgsl:
// A patch of bare earth round a building's foot, drawn on the ground's disc
// (models/ground/ground.py, radius 8) squeezed to the patch's size: the
// trodden earth round the rock's meadow (ground.wgsl), mottled, gritty and
// strewn with a few pebbles, darker right under the building, its edge
// ragged and soft against the floor.
//
// Patches that overlap join into one: each draw knows its neighbours, works
// out the earth of them all together, and draws only where it is the nearest
// of them (measured against each one's ragged edge), so every point is drawn
// once and the seams fall nowhere in particular.
//
// Its extra vectors hold its neighbours, each x, z, radius and seed.
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
};
// What a draw passes (src/earth.blot): the patch's radius, a seed of its
// own, and how many neighbours its extra vectors hold.
struct Parameters {
  radius: f32,
  seed: f32,
  neighbours: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  // x: lit.
  settings: vec4f,
  parameters: Parameters,
  extra: array<vec4f, 16>,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) world: vec3f,
};

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  // It casts no shadow: in the shadow map's orthographic view it is left
  // out, all outside the clip volume.
  if (scene.projection[3].w > 0.5) {
    output.position = vec4f(2.0, 2.0, 2.0, 1.0);
    return output;
  }
  let world = draw.model * vec4f(input.position, 1.0);
  output.position = scene.projection * scene.view * world;
  output.world = world.xyz;
  return output;
}

fn sunlit(world: vec3f) -> f32 {
  if (scene.shadow.x < 0.5) {
    return 1.0;
  }
  let clip = scene.light_view_projection * vec4f(world + vec3f(0.0, scene.shadow.z, 0.0), 1.0);
  let ndc = clip.xyz / clip.w;
  let uv = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
  if (any(uv < vec2f(0.0)) || any(uv > vec2f(1.0)) || ndc.z > 1.0) {
    return 1.0;
  }
  var light = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      light += textureSampleCompareLevel(shadow_map, shadow_sampler,
        uv + vec2f(f32(x), f32(y)) * scene.shadow.y, ndc.z - 0.0004);
    }
  }
  return light / 9.0;
}

fn hash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(12.9898, 78.233))) * 43758.5453);
}
fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2f(1.0, 0.0)), u.x), mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), u.x), u.y);
}
fn fbm(p: vec2f) -> f32 {
  return noise(p) * 0.55 + noise(p * 2.1 + 7.3) * 0.3 + noise(p * 4.3 + 1.9) * 0.15;
}

const earth_dark = vec3f(0.17, 0.115, 0.07);
const earth_mid = vec3f(0.35, 0.255, 0.165);
const earth_dust = vec3f(0.49, 0.4, 0.29);
const pebble_color = vec3f(0.42, 0.41, 0.4);

// How far `p` lies into the patch at `centre` of `radius` and `seed`, as a
// share of the way to its ragged edge (0 at its middle, 1 at its edge), and
// that share at its middle's darkest.
struct Into {
  share: f32,
  edge: f32,
  r: f32,
};
fn into(p: vec2f, centre: vec2f, radius: f32, seed: f32) -> Into {
  let offset = p - centre;
  let r = length(offset);
  let angle = atan2(offset.y, offset.x);
  let ragged = radius * (0.88 + 0.22 * fbm(vec2f(cos(angle), sin(angle)) * 1.6 + seed * 17.0) + 0.08 * (noise(p * 3.0) - 0.5));
  return Into(r / ragged, ragged, r / radius);
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let p = input.world.xz;
  let own = into(p, draw.model[3].xz, max(draw.parameters.radius, 0.3), draw.parameters.seed);
  // The nearest of the patches, and how far into the earth of them all.
  var nearest = own.share;
  var extent = 1.0 - smoothstep(own.edge - 0.35, own.edge + 0.05, own.share * own.edge);
  var under = 1.0 - smoothstep(0.35, 0.75, own.r);
  let count = u32(draw.parameters.neighbours);
  for (var index = 0u; index < min(count, 16u); index++) {
    let other = draw.extra[index];
    let theirs = into(p, other.xy, max(other.z, 0.3), other.w);
    if (theirs.share < own.share) {
      discard;
    }
    nearest = min(nearest, theirs.share);
    extent = max(extent, 1.0 - smoothstep(theirs.edge - 0.35, theirs.edge + 0.05, theirs.share * theirs.edge));
    under = max(under, 1.0 - smoothstep(0.35, 0.75, theirs.r));
  }
  if (extent <= 0.0) {
    discard;
  }
  // Mottled and dusty, more so toward the edge, darker toward the middles
  // where the buildings stand.
  let mottle = fbm(p * 1.3);
  var earth = mix(earth_dark, earth_mid, smoothstep(0.3, 0.68, mottle));
  earth = mix(earth, earth_dust, smoothstep(0.45, 0.8, fbm(p * 0.6 + 3.0)) * smoothstep(0.3, 0.95, nearest) * 0.8);
  // Grit, and a few pebbles.
  let cell = floor(p / 0.05);
  let grit = hash(cell);
  earth *= 1.0 + select(0.0, select(-0.25, 0.2, grit > 0.95), grit > 0.88);
  let stones = floor(p / 0.35);
  let lucky = hash(stones + 5.0);
  let at = (stones + 0.25 + 0.5 * vec2f(hash(stones + 1.7), hash(stones + 9.1))) * 0.35;
  let size = 0.05 + 0.06 * fract(lucky * 31.0);
  let stone = (1.0 - smoothstep(size - 0.02, size, length(p - at))) * step(0.86, lucky);
  earth = mix(earth, pebble_color * (0.7 + 0.5 * fract(lucky * 53.0)), stone);
  earth *= 1.0 - 0.35 * under;
  if (draw.settings.x < 0.5) {
    return vec4f(earth, extent);
  }
  let to_light = normalize(-scene.light_direction.xyz);
  let sun = sunlit(input.world);
  let diffuse = max((to_light.y + 0.1) / 1.1, 0.0);
  return vec4f(earth * (scene.ambient.xyz + scene.light_color.xyz * diffuse * sun), extent);
}

files.src/assets/god_hand.wgsl:
// A sculpted cursor hand of polished alabaster. The wrist follows the
// fingertip exactly; its forearm bends continuously out of the palm and
// dissolves in ordered dots.
struct Scene {
  view: mat4x4f, projection: mat4x4f, ambient: vec4f,
  light_direction: vec4f, light_color: vec4f, light_view_projection: mat4x4f,
  shadow: vec4f, zenith: vec4f, horizon: vec4f, ground: vec4f, eye: vec4f,
};
struct Parameters {
  size: f32,
  press: f32,
  handed: f32,
  fade: f32,
};
struct Draw {
  model: mat4x4f, normal: mat4x4f, color: vec4f, settings: vec4f,
  parameters: Parameters,
  // Cursor x/y, pointing direction x/y, then shoulder/control, then inset.
  aim: vec4f,
  reach: vec4f,
  rectangle: vec4f,
  anchor: vec4f,
  // Cock, release, overhead pinch, side pinch; then the fist, the open palm,
  // the contact's depth and the roll about the forearm (src/god_hand.blot).
  gestures: vec4f,
  details: vec4f,
  packed_min: vec4f,
  packed_span: vec4f,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var stock: texture_2d<f32>;
@group(1) @binding(2) var stock_sampler: sampler;
@group(1) @binding(4) var poses: texture_2d<f32>;
struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
  @location(8) attributes: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) normal: vec3f,
  @location(1) uv: vec2f,
  @location(2) pixel: vec2f,
  @location(3) along: f32,
  // The rest pose's position: veins stay put while the fingers move.
  @location(4) rest: vec3f,
  // How much open sky the posed fingers and palm leave each vertex.
  @location(5) occlusion: f32,
  // What the fingertip wears: 0 nothing, 1 a natural nail, 2 the index's
  // thimble.
  @location(6) @interpolate(flat) nail: f32,
  // Where on that nail: across -1..1, along -1 at the cuticle to 1 at the
  // free edge. On the thimble: round the finger from the pad's seam (-1)
  // over the nail (0) and back, and along from -1 at the tip to 1 at the rim.
  @location(7) place: vec2f,
};

struct Curve { point: vec2f, velocity: vec2f, acceleration: vec2f };
struct Posed { point: vec3f, normal: vec3f, occlusion: f32 };
// A slight roll reveals the curl and thumb saddle at ordinary cursor size;
// the game rolls the hand further to pinch salt and to hold it up in the palm.
fn rolled(p: vec3f) -> vec3f {
  let angle = draw.details.w;
  return vec3f(p.x*cos(angle)+p.z*sin(angle),p.y,-p.x*sin(angle)+p.z*cos(angle));
}
fn pose_texel(index: u32) -> vec4f {
  let width = textureDimensions(poses).x;
  return round(textureLoad(poses, vec2i(i32(index%width), i32(index/width)), 0)*255.0);
}
fn word(bytes: vec2f) -> f32 { return (bytes.x*256.0+bytes.y)/65535.0; }
fn pose_at(vertex: u32, pose: u32) -> Posed {
  let at = (pose*u32(draw.anchor.w)+vertex)*3u;
  let a = pose_texel(at); let b = pose_texel(at+1u); let c = pose_texel(at+2u);
  let point = draw.packed_min.xyz + vec3f(word(a.xy),word(a.zw),word(b.xy))*draw.packed_span.xyz;
  let oct = vec2f(word(b.zw),word(c.xy))*2.0-1.0;
  var n = vec3f(oct, 1.0-abs(oct.x)-abs(oct.y));
  if (n.z<0.0) { n = vec3f((1.0-abs(n.yx))*select(vec2f(-1.0),vec2f(1.0),n.xy>=vec2f(0.0)),n.z); }
  return Posed(point,normalize(n),c.z/255.0);
}
// The nail place rides in the spare byte of the first four poses' third texel.
fn nail_place(vertex: u32) -> vec2f {
  var bytes = vec4f(0.0);
  for (var pose=0u; pose<4u; pose++) {
    bytes[pose] = pose_texel((pose*u32(draw.anchor.w)+vertex)*3u+2u).w;
  }
  return vec2f(word(bytes.xy), word(bytes.zw))*4.0-2.0;
}
fn posed(vertex: u32) -> Posed {
  let g = draw.gestures;
  let d = draw.details;
  let weights = array<f32,7>(max(0.0,1.0-dot(g,vec4f(1.0))-d.x-d.y),g.x,g.y,g.z,g.w,d.x,d.y);
  var point = vec3f(0.0); var normal = vec3f(0.0); var occlusion = 0.0;
  for(var pose=0u;pose<7u;pose++) {
    if(weights[pose]>0.00001) {
      let sample = pose_at(vertex,pose);
      point += sample.point*weights[pose]; normal += sample.normal*weights[pose];
      occlusion += sample.occlusion*weights[pose];
    }
  }
  let mirror = vec3f(draw.parameters.handed,1.0,1.0);
  return Posed(rolled(point)*mirror,normalize(rolled(normal)*mirror),occlusion);
}
fn reach_curve(wrist: vec2f, forward: vec2f, span: f32, t: f32) -> Curve {
  // Equal first two spans preserve the hand's scale and zero curvature at
  // the wrist. The old distance-based cubic stretched it abruptly there.
  let a = wrist;
  let b = a - forward * span / 5.0;
  let c = a - forward * span * 2.0 / 5.0;
  let d = draw.reach.zw;
  let f = draw.reach.xy;
  let e = (d + f) * 0.5;
  let u = 1.0-t;
  let u2 = u*u; let u3 = u2*u; let u4 = u3*u;
  let t2 = t*t; let t3 = t2*t; let t4 = t3*t;
  return Curve(
    a*u4*u + 5.0*b*u4*t + 10.0*c*u3*t2 + 10.0*d*u2*t3 + 5.0*e*u*t4 + f*t4*t,
    5.0*((b-a)*u4 + 4.0*(c-b)*u3*t + 6.0*(d-c)*u2*t2 + 4.0*(e-d)*u*t3 + (f-e)*t4),
    20.0*((c-2.0*b+a)*u3 + 3.0*(d-2.0*c+b)*u2*t + 3.0*(e-2.0*d+c)*u*t2 + (f-2.0*e+d)*t3));
}

// The thimble's metal stands this far off the skin, in the hand's units.
const thimble_wall = 0.011;
@vertex fn vertex(input: VertexInput) -> VertexOutput {
  let shape = posed(u32(input.attributes.x));
  let place = select(vec2f(2.0), nail_place(u32(input.attributes.x)), input.attributes.y > 0.5);
  let covered = select(0.0, 1.0 - smoothstep(0.92, 1.04, place.y), input.attributes.y > 1.5);
  let p = shape.point + shape.normal * thimble_wall * covered;
  let size = draw.parameters.size * (1.0 - draw.parameters.press * 0.05);
  let forward = draw.aim.zw;
  let side = vec2f(-forward.y, forward.x);
  // The model's index tip is its anchor, mirrored for a real left hand.
  let contact=rolled(vec3f(draw.anchor.xy,draw.details.z));
  let tip = vec2f(contact.x * draw.parameters.handed, contact.y);
  let wrist = draw.aim.xy - (side * tip.x + forward * tip.y) * size;
  let t = clamp(-p.y / draw.anchor.z, 0.0, 1.0);
  let curve = reach_curve(wrist, forward, size*draw.anchor.z, t);
  let speed = max(length(curve.velocity), 0.001);
  let tangent = -curve.velocity/speed;
  let across = vec2f(-tangent.y, tangent.x);
  let turning = -(curve.acceleration - tangent*dot(tangent,curve.acceleration))/speed;
  let widening = 0.8 * t*t*t*(t*(6.0*t-15.0)+10.0);
  let width = size * (1.0+widening);
  let width_rate = size * 24.0*t*t*(t-1.0)*(t-1.0);
  let hand = wrist + (side*p.x + forward*p.y)*size;
  let arm = curve.point + across * p.x * width;
  let point = select(hand, arm, p.y < 0.0);
  let arm_dx = across*width;
  let arm_dy = -(curve.velocity + vec2f(-turning.y,turning.x)*p.x*width + across*p.x*width_rate)/draw.anchor.z;
  let dx = select(side*size, arm_dx, p.y < 0.0);
  let dy = select(forward*size, arm_dy, p.y < 0.0);
  // Transform normals by the deformation's actual derivatives. Merely
  // rotating them left a lighting seam between the palm and stretched arm.
  let jx = vec3f(dx.x, -dx.y, 0.0);
  let jy = vec3f(dy.x, -dy.y, select(0.0, -p.z*width_rate/draw.anchor.z, p.y < 0.0));
  let jz = vec3f(0.0, 0.0, width);
  let n = shape.normal;
  var output: VertexOutput;
  let depth = p.z*(1.0+widening);
  output.position = vec4f((point.x-draw.rectangle.x)/draw.rectangle.z*2.0-1.0,
    1.0-(point.y-draw.rectangle.y)/draw.rectangle.w*2.0, 0.5-depth*0.08-t*0.12, 1.0);
  output.normal = normalize(cross(jy,jz)*n.x + cross(jz,jx)*n.y + cross(jx,jy)*n.z);
  output.uv = input.uv;
  output.pixel = point;
  output.along = t;
  output.rest = pose_at(u32(input.attributes.x), 0u).point;
  output.occlusion = shape.occlusion;
  output.nail = input.attributes.y;
  output.place = place;
  return output;
}
// Polished alabaster: ivory where the studio light falls, glowing warm where
// light soaks in near the terminator and where the stone clouds thinner, a
// warm fill bounced up from below and the sky's cool blue in the shade, a pale
// gold rim round the shaded silhouette and a broad, gentle gloss.
const ivory = vec3f(0.98, 0.93, 0.85);
const cloudy = vec3f(0.94, 0.92, 0.9);
const shade = vec3f(0.82, 0.86, 1.0);
const glow = vec3f(1.0, 0.55, 0.32);
const rim = vec3f(1.0, 0.82, 0.5);
const fill = vec3f(1.0, 0.8, 0.62);
const fill_direction = vec3f(0.62, -0.5, 0.6);

fn random(cell: vec3f) -> f32 {
  let c = vec3u(vec3i(cell));
  var h = (c.x * 0x8da6b343u) ^ (c.y * 0xd8163841u) ^ (c.z * 0xcb1ab31fu);
  h ^= h >> 16u;
  h *= 0x7feb352du;
  h ^= h >> 15u;
  h *= 0x846ca68bu;
  h ^= h >> 16u;
  return f32(h >> 8u) / 16777216.0;
}
fn noise(p: vec3f) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(random(i), random(i + vec3f(1.0, 0.0, 0.0)), u.x);
  let b = mix(random(i + vec3f(0.0, 1.0, 0.0)), random(i + vec3f(1.0, 1.0, 0.0)), u.x);
  let c = mix(random(i + vec3f(0.0, 0.0, 1.0)), random(i + vec3f(1.0, 0.0, 1.0)), u.x);
  let d = mix(random(i + vec3f(0.0, 1.0, 1.0)), random(i + vec3f(1.0, 1.0, 1.0)), u.x);
  return mix(mix(a, b, u.y), mix(c, d, u.y), u.z);
}
fn fbm(p: vec3f) -> f32 {
  var sum = 0.0;
  var weight = 0.5;
  var q = p;
  for (var octave = 0u; octave < 3u; octave++) {
    sum += weight * noise(q);
    q = q * 2.07 + vec3f(3.1, -1.7, 2.3);
    weight *= 0.5;
  }
  return sum / 0.875;
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let texel = textureSample(stock, stock_sampler, input.uv);
  // Fixed in screen pixels: the fade has no noisy temporal flicker.
  let fade = smoothstep(0.32, 0.98, input.along);
  let cell = fract(input.pixel / 5.0) - vec2f(0.5);
  let radius = sqrt(fade) * 0.72;
  if (length(cell) < radius || draw.parameters.fade <= 0.0) { discard; }
  let normal = normalize(input.normal + vec3f(dpdx(texel.a), -dpdy(texel.a), 0.0) * 0.05);
  let light = normalize(-scene.light_direction.xyz);
  let eye = vec3f(0.0, 0.0, 1.0);
  // The rest pose holds the clouds still while the fingers move.
  let cloud = smoothstep(0.3, 0.75, fbm(input.rest * 1.2));
  let albedo = mix(ivory, cloudy, cloud) * texel.rgb;
  let facing = dot(normal, light);
  // Light wraps past the terminator, reddened by the depth it travelled.
  let wrapped = max((facing + 0.3) / 1.3, 0.0);
  let soak = smoothstep(-0.3, 0.1, facing) * (1.0 - smoothstep(0.1, 0.6, facing));
  // Light scattered through the stone keeps creases warm rather than grey.
  let open = mix(0.5, 1.0, input.occlusion);
  let sky = scene.ambient.rgb * shade * (0.62 + 0.18 * normal.y) * open;
  let direct = scene.light_color.rgb * wrapped * 0.92 * open;
  let bounce = fill * max((dot(normal, normalize(fill_direction)) + 0.2) / 1.2, 0.0) * 0.3 * open;
  let diffuse = albedo * (sky + direct + bounce) + albedo * glow * (soak * mix(0.24, 0.1, cloud) + (1.0 - input.occlusion) * 0.1);
  let edge = pow(1.0 - clamp(dot(normal, eye), 0.0, 1.0), 2.5) * (0.2 + 0.4 * (1.0 - wrapped)) * open;
  let halfway = normalize(light + eye);
  let lobe = max(dot(normal, halfway), 0.0);
  let gloss = pow(lobe, 40.0) * 0.12 + pow(lobe, 8.0) * 0.05;
  var color = diffuse + rim * edge + scene.light_color.rgb * gloss;
  // A painted nail: a rounded plate, rounder at the cuticle than at the free
  // edge, cut with a soft groove where the skin folds over its cuticle and
  // sides. Worked out everywhere so its edge can be smoothed by the pixel.
  let q = input.place;
  let corner = select(0.3, 0.6, q.y < 0.0);
  let reach = max(abs(q) - vec2f(1.0 - corner), vec2f(0.0));
  let outside = length(reach) + min(max(abs(q.x), abs(q.y)) - 1.0 + corner, 0.0) - corner;
  let soft = max(fwidth(outside), 0.015);
  let painted = select(0.0, 1.0, input.nail > 0.5 && input.nail < 1.5);
  let plate = (1.0 - smoothstep(-soft, soft, outside)) * painted;
  let fold = (1.0 - smoothstep(0.0, 0.22, abs(outside))) * (1.0 - smoothstep(0.7, 0.95, q.y)) * painted;
  color *= 1.0 - fold * 0.22;
  // Natural nails: smoother, faintly rosier stone with a paler free edge.
  let free_edge = smoothstep(0.62, 0.8, q.y);
  let stone = mix(vec3f(0.97, 0.89, 0.86), vec3f(1.0, 0.97, 0.93), free_edge) * texel.rgb;
  let lit = stone * (sky + direct + bounce) + stone * glow * soak * 0.12;
  let coat = pow(lobe, 70.0) * 0.35 + pow(lobe, 14.0) * 0.06;
  let sheen = pow(1.0 - clamp(dot(normal, eye), 0.0, 1.0), 4.0) * 0.12 * open;
  color = mix(color, lit + scene.light_color.rgb * coat + vec3f(sheen), plate);
  // The index's thimble: polished silver pitted in staggered rows, under a
  // plain domed top and above a rolled rim, mirroring the studio's bright sky,
  // its dark floor and a sharp highlight of the light. Solid metal, it stays
  // opaque however see-through the stone is.
  let wearing = select(0.0, 1.0, input.nail > 1.5);
  let lip = max(fwidth(q.y), 0.02);
  let worn = (1.0 - smoothstep(1.0 - lip, 1.0 + lip, q.y)) * wearing;
  let rows = (q.y + 1.0) * 3.2;
  let row = floor(rows);
  let around = (q.x + 1.0) * 7.0 + 0.5 * (row - 2.0 * floor(row * 0.5));
  // Pits too small to see the shape of fade out rather than speckle.
  let tiny = smoothstep(0.18, 0.32, max(fwidth(rows), fwidth(around)));
  let pit = (1.0 - smoothstep(0.16, 0.34, length(vec2f(fract(around), fract(rows)) - 0.5)))
    * smoothstep(-0.72, -0.6, q.y) * (1.0 - smoothstep(0.7, 0.78, q.y)) * (1.0 - tiny);
  let roll = smoothstep(0.8, 0.9, q.y) * (1.0 - smoothstep(0.95, 1.0, q.y));
  let dented = normalize(normal + vec3f(dpdx(roll - pit), -dpdy(roll - pit), 0.0) * 0.6);
  let mirrored = reflect(-eye, dented);
  // Satin rather than chrome: the floor's reflection is a soft grey, not
  // black, so the small cap keeps its shape at any size.
  let environment = mix(vec3f(0.36, 0.37, 0.4), vec3f(0.95, 0.96, 0.99), smoothstep(-0.6, 0.6, mirrored.y))
    + vec3f(0.25) * exp(-abs(mirrored.y) * 6.0);
  let shine = max(dot(mirrored, light), 0.0);
  let metal = vec3f(0.9, 0.9, 0.92) * (environment * mix(0.65, 1.0, input.occlusion) * (1.0 - pit * 0.35 - tiny * 0.08)
    + scene.light_color.rgb * (pow(shine, 60.0) * 1.6 + pow(shine, 8.0) * 0.3));
  // The skin just below the rim lies in the metal's shadow.
  color *= 1.0 - wearing * (1.0 - worn) * (1.0 - smoothstep(1.0, 1.18, q.y)) * 0.3;
  color = mix(color, metal, worn);
  let opacity = max(mix(0.8, 0.38, smoothstep(0.0, 0.48, input.along)), worn);
  // Insets composite premultiplied coverage after tone mapping.
  return vec4f(min(color, vec3f(1.0)) * opacity, opacity);
}

files.src/assets/grass.wgsl:
// Grass blades round the rock, grown in Blender with geometry nodes
// (models/ground/grass.py): curved, tapering blades in soft clumps, leaning
// out from their middles, on the patch round the rock's foot. Each vertex
// carries its blade's root on the floor (uv: x, z), how far up the blade it
// is (attributes.x: 0 at the root, 1 at the tip) and the blade's own random
// value (attributes.y); its normal looks out of the blade's bend. Blades on
// the trodden earth past the grass, or deep in the salt spilled at the
// rock's foot, are gone, and those near the earth stand shorter.
//
// The blades take their color from the meadow under them (as ground.wgsl
// works it out), darker at the root and lighter and warmer toward the tip,
// and sunlight shines through them when they stand against it. The wind
// sways their tips, more as gusts roll across the grass. The renderer culls
// back faces, so a blade seen from behind turns to face the camera (and the
// light, as it casts its shadow): mirrored about its own middle, which keeps
// its shape and bend.
//
// The same shader draws the tufts round each building's foot
// (models/ground/tufts.py), in the building's own frame: their roots and
// blades are placed by the draw's model matrix, and none are culled.
//
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  // x: 1 with a shadow map, y: its texel in texture coordinates, z: how far
  // off the surface to read it, in world units.
  shadow: vec4f,
};
// What a draw passes: the time in seconds, the radius of the rock's
// footprint, and 1 for a building's tufts (src/meadow.blot, src/buildings.blot,
// src/depot.blot).
struct Parameters {
  seconds: f32,
  footprint: f32,
  tufts: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  // x: lit.
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
  @location(8) attributes: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) world: vec3f,
  // The blade's front, turned toward the camera.
  @location(1) normal: vec3f,
  // The meadow's color under the blade.
  @location(2) base: vec3f,
  // How far up the blade, and the blade's own shade, 0..1.
  @location(3) up: f32,
  @location(4) shade: f32,
  // Where the blade stands on the ground, whose shadow it takes.
  @location(5) root: vec3f,
};


// How much sunlight reaches `world`, as in scene.wgsl.
fn sunlit(world: vec3f, normal: vec3f) -> f32 {
  if (scene.shadow.x < 0.5) {
    return 1.0;
  }
  let clip = scene.light_view_projection * vec4f(world + normal * scene.shadow.z, 1.0);
  let ndc = clip.xyz / clip.w;
  let uv = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
  if (any(uv < vec2f(0.0)) || any(uv > vec2f(1.0)) || ndc.z > 1.0) {
    return 1.0;
  }
  var light = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      light += textureSampleCompareLevel(shadow_map, shadow_sampler,
        uv + vec2f(f32(x), f32(y)) * scene.shadow.y, ndc.z - 0.0004);
    }
  }
  return light / 9.0;
}

// ---- The meadow, as ground.wgsl also works it out. ----

// A well-mixed 32-bit hash of the whole-numbered `cell` and `seed`.
fn hash(cell: vec2f, seed: u32) -> u32 {
  let c = vec2u(vec2i(cell));
  var h = c.x * 0x8da6b343u + c.y * 0xd8163841u + seed * 0xcb1ab31fu;
  h ^= h >> 16u;
  h *= 0x7feb352du;
  h ^= h >> 15u;
  h *= 0x846ca68bu;
  h ^= h >> 16u;
  return h;
}
// A random value in 0..1 for the whole-numbered `cell` and `seed`.
fn random(cell: vec2f, seed: u32) -> f32 {
  return f32(hash(cell, seed) >> 8u) / 16777216.0;
}
// Smooth noise in 0..1: random values at whole numbers, eased between.
fn noise(p: vec2f, seed: u32) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(random(i, seed), random(i + vec2f(1.0, 0.0), seed), u.x),
    mix(random(i + vec2f(0.0, 1.0), seed), random(i + vec2f(1.0, 1.0), seed), u.x),
    u.y,
  );
}
// Octaves of noise, each twice as fine and turned, so no grid shows: 0..1,
// mostly within 0.25..0.75.
fn fbm(p: vec2f, seed: u32, octaves: i32) -> f32 {
  var sum = 0.0;
  var weight = 0.5;
  var total = 0.0;
  var q = p;
  for (var octave = 0; octave < octaves; octave++) {
    sum += weight * noise(q, seed + u32(octave) * 101u);
    total += weight;
    q = mat2x2f(1.6, 1.2, -1.2, 1.6) * q + vec2f(5.3, -2.9);
    weight *= 0.5;
  }
  return sum / total;
}
// A random slant, x and y in -1..1, for the whole-numbered `cell`.
fn slant(cell: vec2f, seed: u32) -> vec2f {
  let h = hash(cell, seed);
  return vec2f(f32(h & 0xffffu), f32(h >> 16u)) / 32767.5 - 1.0;
}
// Gradient noise, which shows no grid even when sharpened: about -0.8..0.8,
// and its slope along x and along y.
fn wave(p: vec2f, seed: u32) -> vec3f {
  let i = floor(p);
  let f = p - i;
  let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  let du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  let ga = slant(i, seed);
  let gb = slant(i + vec2f(1.0, 0.0), seed);
  let gc = slant(i + vec2f(0.0, 1.0), seed);
  let gd = slant(i + vec2f(1.0, 1.0), seed);
  let va = dot(ga, f);
  let vb = dot(gb, f - vec2f(1.0, 0.0));
  let vc = dot(gc, f - vec2f(0.0, 1.0));
  let vd = dot(gd, f - vec2f(1.0, 1.0));
  let k = va - vb - vc + vd;
  return vec3f(
    va + u.x * (vb - va) + u.y * (vc - va) + u.x * u.y * k,
    ga + u.x * (gb - ga) + u.y * (gc - ga) + u.x * u.y * (ga - gb - gc + gd) +
      du * (u.yx * k + vec2f(vb, vc) - va),
  );
}

// The grass round the rock's foot, whose radius is `footprint`, and the
// trodden earth round it: how far past the foot the grass reaches at `p`,
// about one to one and three quarter units, wandering and ragged; and how
// bare the floor is `r` from the middle with the grass's edge `edge` from it:
// 0 in the grass, 1 on the earth.
fn reach(p: vec2f) -> f32 {
  let wandering = 0.5 * smoothstep(0.3, 0.7, fbm(p * 0.6, 11u, 2));
  return 1.05 + wandering + (fbm(p * 1.9, 13u, 2) - 0.5) * 0.5;
}
fn bareness(r: f32, edge: f32) -> f32 {
  return smoothstep(edge - 0.3, edge + 0.3, r);
}

// The salt spilled at the rock's foot: how far past the foot it lies at
// `p`, a ragged quarter to two thirds of a unit.
fn spill(p: vec2f) -> f32 {
  return 0.25 + 0.45 * noise(p * 1.7 + vec2f(9.0, 2.0), 71u);
}

// The edge of it all, past the earth: how far past the rock's foot the
// ground reaches at `p`, `reached` being how far the grass does there, the
// earth a ragged band about a unit wide; and how much of the ground there is
// at `p`, 1 within, 0 beyond, thinning over its last half unit. No grass
// grows past `farthest` from the foot.
const farthest = 2.1;
fn spread(p: vec2f, reached: f32) -> f32 {
  let around = p / max(length(p), 0.001);
  return reached + 0.8 + 0.6 * fbm(around * 1.7 + vec2f(4.0, 1.0), 31u, 2) + (noise(p * 2.6, 33u) - 0.5) * 0.3;
}
fn lawn(p: vec2f, footprint: f32, reached: f32) -> f32 {
  let edge = footprint + spread(p, reached);
  return 1.0 - smoothstep(edge - 0.5, edge, length(p));
}

// The way the wind blows over the floor, and how hard it gusts at `p` at
// `seconds`, 0..1: long bands of gusts roll across the meadow along it.
const wind = vec2f(0.86, 0.51);
fn gust(p: vec2f, seconds: f32) -> f32 {
  let along = dot(p, wind) - seconds * 2.4;
  let across = dot(p, vec2f(-wind.y, wind.x));
  let broad = noise(vec2f(along * 0.2, across * 0.09), 61u);
  let gusty = noise(vec2f(along * 0.53, across * 0.3), 67u);
  return smoothstep(0.35, 0.8, broad * 0.7 + gusty * 0.3);
}

// The sward's tufts: how high it stands at `p`, about 0..1, and its slope
// per unit of that along x and z: tufts about a third of a unit across.
fn tufts(p: vec2f) -> vec3f {
  let a = wave(p * 3.0, 81u);
  return vec3f(0.5 + 0.7 * a.x, a.yz * 2.1);
}

// Clean, bright anime greens.
const grass_deep = vec3f(0.07, 0.27, 0.09);
const grass_mid = vec3f(0.17, 0.47, 0.13);
const grass_bright = vec3f(0.38, 0.68, 0.18);
const grass_warm = vec3f(0.55, 0.7, 0.2);
const grass_cool = vec3f(0.08, 0.4, 0.24);
// How much darker the grass is at its roots, as the ground under it is too,
// so the blades rise out of it with no seam.
const root_shade = vec3f(0.7, 0.77, 0.78);

// The meadow's color at `p`, in broad strokes: lush and paler patches, and
// a warmer and a cooler hue wandering over them, a couple of units across.
fn meadow(p: vec2f) -> vec3f {
  let broad = fbm(p * 0.45, 21u, 3);
  let medium = fbm(p * 0.9, 23u, 2);
  let hue = noise(p * 0.35 + vec2f(7.0, 3.0), 25u);
  var color = mix(grass_deep, grass_mid, smoothstep(0.25, 0.55, broad));
  color = mix(color, grass_bright, smoothstep(0.45, 0.75, medium) * 0.75);
  color = mix(color, grass_cool, smoothstep(0.5, 0.28, hue) * 0.55);
  return mix(color, grass_warm, smoothstep(0.52, 0.74, hue) * 0.55);
}
// The grass's color in the meadow's `tone` where its tufts stand `tuft`
// high: warmer and lighter on top, cooler and darker in the hollows between,
// the more so for `contrast` (0..1).
fn sward(tone: vec3f, tuft: f32, contrast: f32) -> vec3f {
  let top = mix(0.5, smoothstep(0.15, 0.85, tuft), contrast);
  let hollow = tone * vec3f(0.7, 0.76, 0.84);
  return mix(hollow, tone * vec3f(1.24, 1.2, 1.0) + vec3f(0.012, 0.012, 0.0), top);
}

// ---- The blades. ----

// The way toward the eye from `at`: toward the camera, or, for the shadow
// map's orthographic view, toward the light.
fn toward_eye(at: vec3f) -> vec3f {
  if (scene.projection[3].w > 0.5) {
    return vec3f(scene.view[0].z, scene.view[1].z, scene.view[2].z);
  }
  let rotation = mat3x3f(scene.view[0].xyz, scene.view[1].xyz, scene.view[2].xyz);
  return -(transpose(rotation) * scene.view[3].xyz) - at;
}

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let seconds = draw.parameters.seconds;
  let footprint = draw.parameters.footprint;
  let tufted = draw.parameters.tufts > 0.5;
  let local_root = vec3f(input.uv.x, 0.0, input.uv.y);
  let up = input.attributes.x;
  let luck = input.attributes.y;
  // A building's tufts are in its frame.
  let turn = mat3x3f(draw.model[0].xyz, draw.model[1].xyz, draw.model[2].xyz);
  let root = select(local_root, (draw.model * vec4f(local_root, 1.0)).xyz, tufted);

  // Blades on the trodden earth are gone; toward it they stand shorter, the
  // unlucky ones first. Nor do any grow deep in the salt spilled at the
  // rock's foot. A building's tufts all stand.
  let bare = bareness(length(root.xz), footprint + reach(root.xz));
  let stands = select(1.0 - smoothstep(0.15, 0.65, bare + (luck - 0.5) * 0.4), 1.0, tufted);
  if (!tufted && (stands < 0.05 || length(root.xz) < footprint + spill(root.xz) * 0.6)) {
    // Outside the clip volume: nothing of it is drawn.
    output.position = vec4f(2.0, 2.0, 2.0, 1.0);
    return output;
  }

  var offset = (input.position - local_root) * mix(0.4, 1.0, stands);
  var normal = normalize(input.normal);
  if (tufted) {
    offset = turn * offset;
    normal = normalize(turn * normal);
  }
  // Across the blade, to its right: its normal's level part, turned.
  let level = normalize(vec2f(normal.x, normal.z) + vec2f(0.00001, 0.0));
  let across = vec3f(level.y, 0.0, -level.x);
  // Seen from behind, the blade turns about its middle to face the eye.
  if (dot(normal, toward_eye(root)) < 0.0) {
    offset -= 2.0 * dot(offset, across) * across;
    normal = -normal;
  }

  // The wind bends the blade along it, the tip most: gently all the time,
  // hard in the gusts, each blade a little out of step.
  let gusting = gust(root.xz, seconds);
  let sway = sin(seconds * 1.9 + luck * 6.2831853 + dot(root.xz, wind) * 0.7);
  let flutter = sin(seconds * 5.3 + luck * 17.0) * gusting;
  let height = max(offset.y, 0.0);
  let lean = (0.1 + 0.06 * sway + 0.42 * gusting) * up;
  let bend = vec3f(wind.x, 0.0, wind.y) * lean * height + across * flutter * 0.05 * height * up;
  // Bent over, it stands lower, keeping about its length.
  offset.y -= height * lean * lean * 0.5;
  let world = root + offset + bend;

  // Grass casts no shadow of its own, which would speckle it blade by blade
  // with dark gaps: in the shadow map's orthographic view it is left out.
  if (scene.projection[3].w > 0.5) {
    output.position = vec4f(2.0, 2.0, 2.0, 1.0);
    return output;
  }
  output.position = scene.projection * scene.view * vec4f(world, 1.0);
  output.world = world;
  output.root = root;
  output.normal = normal;
  output.base = sward(meadow(root.xz), tufts(root.xz).x, 1.0) * (1.0 + 0.12 * gusting);
  output.up = up;
  output.shade = luck;
  return output;
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let up = input.up;
  // A clean gradient, as anime grass is painted: the root as dark as the
  // ground it rises from, the meadow's own green up the blade, a little
  // lighter and warmer at the tip; each blade barely its own, so the grass
  // blends into one mass. Further off, where a blade is less than a pixel or
  // two, it blends into the meadow's green altogether.
  let base = input.base;
  // The root is the very color of the ground under it, and stays dark a
  // way up, as deep in the grass the light hardly reaches, so the blades melt
  // into the ground and their feet never show.
  let root_color = base * root_shade * 0.78;
  let tip_color = mix(base * 1.2, vec3f(0.72, 0.86, 0.4), 0.22);
  var albedo = mix(root_color, base, smoothstep(0.12, 0.75, up));
  albedo = mix(albedo, tip_color, smoothstep(0.55, 1.0, up)) * (0.97 + 0.06 * input.shade);
  let pixel = length(fwidth(input.world));
  albedo = mix(albedo, base * mix(root_shade, vec3f(1.0), 0.7), smoothstep(0.02, 0.08, pixel));
  if (draw.settings.x < 0.5) {
    return vec4f(albedo, 1.0);
  }
  // Lit as one soft mass, by the ground's light rather than each blade's
  // facing, so the grass does not flicker blade by blade; and in steps, sun
  // or shade, the shade a cool green.
  let to_light = normalize(-scene.light_direction.xyz);
  // Shadowed as the ground under the blade is, so a shadow falls across the
  // grass in one piece.
  let sun = sunlit(input.root, vec3f(0.0, 1.0, 0.0));
  let overhead = max(to_light.y, 0.0);
  let sunny = smoothstep(0.4, 0.6, sun) * smoothstep(0.0, 0.12, overhead);
  let shade = albedo * (scene.ambient.xyz * 1.5 + vec3f(0.0, 0.025, 0.05));
  let sunlit_color = albedo * (scene.ambient.xyz + scene.light_color.xyz * (0.6 + 0.4 * overhead));
  var lit = mix(shade, sunlit_color, sunny);
  lit *= mix(0.82, 1.0, smoothstep(0.0, 0.45, up));
  // Tips glow with the sun behind them.
  let rotation = mat3x3f(scene.view[0].xyz, scene.view[1].xyz, scene.view[2].xyz);
  let eye = -(transpose(rotation) * scene.view[3].xyz);
  let to_eye = normalize(eye - input.world);
  let into_sun = pow(max(dot(to_eye, -to_light), 0.0), 3.0);
  lit += tip_color * scene.light_color.xyz * into_sun * smoothstep(0.4, 1.0, up) * sunny * 0.5;
  return vec4f(lit, 1.0);
}

