// The patch of grass round the rock (models/ground), on a disc of ground
// under it. Its look is all worked out here from where it lies, so nothing
// repeats: grass from the rock's foot out a unit or two, in lush and paler
// patches with a warmer and a cooler hue wandering over them, in tufts
// lighter and warmer on top than in the hollows between, with blades showing
// close up and a rare tiny flower; then a ragged band of bare, trodden earth
// round it, lumpy, gritty and strewn with pebbles and crumbs of salt, which
// tufts of grass creep into, fading into the floor at its ragged edge (the
// material blends). The ground darkens right at the rock's base and pales as
// gusts roll over the grass. It casts no shadow.
//
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  // x: 1 with a shadow map, y: its texel in texture coordinates, z: how far
  // off the surface to read it, in world units.
  shadow: vec4f,
};
// What a draw passes (src/meadow.blot): the time in seconds, and the radius
// of the rock's footprint, which the trodden ring follows as the rock changes.
struct Parameters {
  seconds: f32,
  footprint: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  // x: lit.
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) world: vec3f,
  // What varies slowly over the meadow, worked out at its vertices, which
  // lie closest near the rock: its color in broad strokes,
  @location(1) tone: vec3f,
  // how hard the wind gusts, how far past the rock's foot the trodden
  // earth's edge lies, how damp the earth is and how dusty,
  @location(2) slow: vec4f,
  // and the earth's mottling.
  @location(3) mottle: f32,
  // Where the eye is.
  @location(4) @interpolate(flat) eye: vec3f,
};

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  // Lying flat on the floor, it casts no shadow worth drawing: in the shadow
  // map's orthographic view it is left out, all outside the clip volume.
  if (scene.projection[3].w > 0.5) {
    output.position = vec4f(2.0, 2.0, 2.0, 1.0);
    return output;
  }
  let world = draw.model * vec4f(input.position, 1.0);
  let p = world.xz;
  output.position = scene.projection * scene.view * world;
  output.world = world.xyz;
  output.tone = meadow(p);
  output.slow = vec4f(
    gust(p, draw.parameters.seconds),
    reach(p),
    smoothstep(0.45, 0.75, fbm(p * 0.45 + vec2f(3.0, 9.0), 53u, 2)),
    smoothstep(0.25, 0.6, fbm(p * 0.6, 55u, 2)),
  );
  output.mottle = fbm(p * 1.3, 51u, 2);
  let rotation = mat3x3f(scene.view[0].xyz, scene.view[1].xyz, scene.view[2].xyz);
  output.eye = -(transpose(rotation) * scene.view[3].xyz);
  return output;
}

// How much sunlight reaches `world`, as in scene.wgsl.
fn sunlit(world: vec3f, normal: vec3f) -> f32 {
  if (scene.shadow.x < 0.5) {
    return 1.0;
  }
  let clip = scene.light_view_projection * vec4f(world + normal * scene.shadow.z, 1.0);
  let ndc = clip.xyz / clip.w;
  let uv = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
  if (any(uv < vec2f(0.0)) || any(uv > vec2f(1.0)) || ndc.z > 1.0) {
    return 1.0;
  }
  var light = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      light += textureSampleCompareLevel(shadow_map, shadow_sampler,
        uv + vec2f(f32(x), f32(y)) * scene.shadow.y, ndc.z - 0.0004);
    }
  }
  return light / 9.0;
}

// ---- The meadow, as grass.wgsl also works it out. ----

// A well-mixed 32-bit hash of the whole-numbered `cell` and `seed`.
fn hash(cell: vec2f, seed: u32) -> u32 {
  let c = vec2u(vec2i(cell));
  var h = c.x * 0x8da6b343u + c.y * 0xd8163841u + seed * 0xcb1ab31fu;
  h ^= h >> 16u;
  h *= 0x7feb352du;
  h ^= h >> 15u;
  h *= 0x846ca68bu;
  h ^= h >> 16u;
  return h;
}
// A random value in 0..1 for the whole-numbered `cell` and `seed`.
fn random(cell: vec2f, seed: u32) -> f32 {
  return f32(hash(cell, seed) >> 8u) / 16777216.0;
}
// Smooth noise in 0..1: random values at whole numbers, eased between.
fn noise(p: vec2f, seed: u32) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(random(i, seed), random(i + vec2f(1.0, 0.0), seed), u.x),
    mix(random(i + vec2f(0.0, 1.0), seed), random(i + vec2f(1.0, 1.0), seed), u.x),
    u.y,
  );
}
// Octaves of noise, each twice as fine and turned, so no grid shows: 0..1,
// mostly within 0.25..0.75.
fn fbm(p: vec2f, seed: u32, octaves: i32) -> f32 {
  var sum = 0.0;
  var weight = 0.5;
  var total = 0.0;
  var q = p;
  for (var octave = 0; octave < octaves; octave++) {
    sum += weight * noise(q, seed + u32(octave) * 101u);
    total += weight;
    q = mat2x2f(1.6, 1.2, -1.2, 1.6) * q + vec2f(5.3, -2.9);
    weight *= 0.5;
  }
  return sum / total;
}
// A random slant, x and y in -1..1, for the whole-numbered `cell`.
fn slant(cell: vec2f, seed: u32) -> vec2f {
  let h = hash(cell, seed);
  return vec2f(f32(h & 0xffffu), f32(h >> 16u)) / 32767.5 - 1.0;
}
// Gradient noise, which shows no grid even when sharpened: about -0.8..0.8,
// and its slope along x and along y.
fn wave(p: vec2f, seed: u32) -> vec3f {
  let i = floor(p);
  let f = p - i;
  let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  let du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  let ga = slant(i, seed);
  let gb = slant(i + vec2f(1.0, 0.0), seed);
  let gc = slant(i + vec2f(0.0, 1.0), seed);
  let gd = slant(i + vec2f(1.0, 1.0), seed);
  let va = dot(ga, f);
  let vb = dot(gb, f - vec2f(1.0, 0.0));
  let vc = dot(gc, f - vec2f(0.0, 1.0));
  let vd = dot(gd, f - vec2f(1.0, 1.0));
  let k = va - vb - vc + vd;
  return vec3f(
    va + u.x * (vb - va) + u.y * (vc - va) + u.x * u.y * k,
    ga + u.x * (gb - ga) + u.y * (gc - ga) + u.x * u.y * (ga - gb - gc + gd) +
      du * (u.yx * k + vec2f(vb, vc) - va),
  );
}

// The grass round the rock's foot, whose radius is `footprint`, and the
// trodden earth round it: how far past the foot the grass reaches at `p`,
// about one to one and three quarter units, wandering and ragged; and how
// bare the floor is `r` from the middle with the grass's edge `edge` from it:
// 0 in the grass, 1 on the earth.
fn reach(p: vec2f) -> f32 {
  let wandering = 0.5 * smoothstep(0.3, 0.7, fbm(p * 0.6, 11u, 2));
  return 1.05 + wandering + (fbm(p * 1.9, 13u, 2) - 0.5) * 0.5;
}
fn bareness(r: f32, edge: f32) -> f32 {
  return smoothstep(edge - 0.3, edge + 0.3, r);
}

// The salt spilled at the rock's foot: how far past the foot it lies at
// `p`, a ragged quarter to two thirds of a unit.
fn spill(p: vec2f) -> f32 {
  return 0.25 + 0.45 * noise(p * 1.7 + vec2f(9.0, 2.0), 71u);
}

// The edge of it all, past the earth: how far past the rock's foot the
// ground reaches at `p`, `reached` being how far the grass does there, the
// earth a ragged band about a unit wide; and how much of the ground there is
// at `p`, 1 within, 0 beyond, thinning over its last half unit. No grass
// grows past `farthest` from the foot.
const farthest = 2.1;
fn spread(p: vec2f, reached: f32) -> f32 {
  let around = p / max(length(p), 0.001);
  return reached + 0.8 + 0.6 * fbm(around * 1.7 + vec2f(4.0, 1.0), 31u, 2) + (noise(p * 2.6, 33u) - 0.5) * 0.3;
}
fn lawn(p: vec2f, footprint: f32, reached: f32) -> f32 {
  let edge = footprint + spread(p, reached);
  return 1.0 - smoothstep(edge - 0.5, edge, length(p));
}

// The way the wind blows over the floor, and how hard it gusts at `p` at
// `seconds`, 0..1: long bands of gusts roll across the meadow along it.
const wind = vec2f(0.86, 0.51);
fn gust(p: vec2f, seconds: f32) -> f32 {
  let along = dot(p, wind) - seconds * 2.4;
  let across = dot(p, vec2f(-wind.y, wind.x));
  let broad = noise(vec2f(along * 0.2, across * 0.09), 61u);
  let gusty = noise(vec2f(along * 0.53, across * 0.3), 67u);
  return smoothstep(0.35, 0.8, broad * 0.7 + gusty * 0.3);
}

// The sward's tufts: how high it stands at `p`, about 0..1, and its slope
// per unit of that along x and z: tufts about a third of a unit across.
fn tufts(p: vec2f) -> vec3f {
  let a = wave(p * 3.0, 81u);
  return vec3f(0.5 + 0.7 * a.x, a.yz * 2.1);
}

// Clean, bright anime greens.
const grass_deep = vec3f(0.07, 0.27, 0.09);
const grass_mid = vec3f(0.17, 0.47, 0.13);
const grass_bright = vec3f(0.38, 0.68, 0.18);
const grass_warm = vec3f(0.55, 0.7, 0.2);
const grass_cool = vec3f(0.08, 0.4, 0.24);
// How much darker the grass is at its roots, as the ground under it is too,
// so the blades rise out of it with no seam.
const root_shade = vec3f(0.7, 0.77, 0.78);

// The meadow's color at `p`, in broad strokes: lush and paler patches, and
// a warmer and a cooler hue wandering over them, a couple of units across.
fn meadow(p: vec2f) -> vec3f {
  let broad = fbm(p * 0.45, 21u, 3);
  let medium = fbm(p * 0.9, 23u, 2);
  let hue = noise(p * 0.35 + vec2f(7.0, 3.0), 25u);
  var color = mix(grass_deep, grass_mid, smoothstep(0.25, 0.55, broad));
  color = mix(color, grass_bright, smoothstep(0.45, 0.75, medium) * 0.75);
  color = mix(color, grass_cool, smoothstep(0.5, 0.28, hue) * 0.55);
  return mix(color, grass_warm, smoothstep(0.52, 0.74, hue) * 0.55);
}
// The grass's color in the meadow's `tone` where its tufts stand `tuft`
// high: warmer and lighter on top, cooler and darker in the hollows between,
// the more so for `contrast` (0..1).
fn sward(tone: vec3f, tuft: f32, contrast: f32) -> vec3f {
  let top = mix(0.5, smoothstep(0.15, 0.85, tuft), contrast);
  let hollow = tone * vec3f(0.7, 0.76, 0.84);
  return mix(hollow, tone * vec3f(1.24, 1.2, 1.0) + vec3f(0.012, 0.012, 0.0), top);
}

// ---- The floor itself. ----

const earth_dark = vec3f(0.17, 0.115, 0.07);
const earth_mid = vec3f(0.35, 0.255, 0.165);
const earth_dust = vec3f(0.49, 0.4, 0.29);
const pebble_color = vec3f(0.33, 0.3, 0.26);
const salt_crumb = vec3f(0.78, 0.77, 0.73);
const flower_white = vec3f(0.95, 0.94, 0.88);
const flower_yellow = vec3f(0.98, 0.8, 0.18);
const flower_violet = vec3f(0.72, 0.6, 0.95);

// Blades of grass seen from above, `p` in cells: a short stroke a cell,
// tapering to its ends, each its own way. Each reaches less than half a cell
// from its middle, so only the four cells nearest `p` can hold one covering
// it. How much of one covers `p`, and its shade, 0..1.
fn strokes(p: vec2f, seed: u32) -> vec2f {
  let base = floor(p - 0.5);
  var found = vec2f(0.0, 0.5);
  for (var y = 0; y <= 1; y++) {
    for (var x = 0; x <= 1; x++) {
      let cell = base + vec2f(f32(x), f32(y));
      let h = hash(cell, seed);
      let middle = cell + vec2f(f32(h & 0xffu), f32((h >> 8u) & 0xffu)) / 255.0;
      let way = normalize(vec2f(f32((h >> 16u) & 0xffu), f32(h >> 24u)) - 127.5 + 0.25);
      let apart = p - middle;
      let along = clamp(dot(apart, way), -0.4, 0.4);
      let width = 0.16 * (1.0 - abs(along) * 1.6);
      let cover = 1.0 - smoothstep(width * 0.55, width, length(apart - way * along));
      if (cover > found.x) {
        found = vec2f(cover, f32((h * 0x9e3779b9u) >> 24u) / 255.0);
      }
    }
  }
  return found;
}

// Something small in the cell of `p` (in cells), or not: a flower, a pebble.
// Each lies within its own cell, so only that cell is looked at: its random
// value, by which it is one or not, and its offset from `p` in cells.
struct Speck {
  kind: f32,
  offset: vec2f,
};
fn speck_at(p: vec2f, seed: u32, margin: f32) -> Speck {
  let cell = floor(p);
  let h = hash(cell, seed);
  let place = vec2f(f32(h & 0xffu), f32((h >> 8u) & 0xffu)) / 255.0;
  return Speck(f32(h >> 16u) / 65536.0, p - (cell + margin + (1.0 - 2.0 * margin) * place));
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let p = input.world.xz;
  let footprint = draw.parameters.footprint;
  let r = length(p);
  let gusting = input.slow.x;
  // A screen pixel's width here, in world units: detail finer than a few of
  // them fades out rather than shimmer, and once it has, it is skipped.
  let pixel = max(length(fwidth(p)), 0.0001);
  let fine = 1.0 - smoothstep(0.025, 0.07, pixel);
  let finest = 1.0 - smoothstep(0.008, 0.022, pixel);
  // Past the earth's edge there is only the floor.
  let extent = lawn(p, footprint, input.slow.y);
  if (extent <= 0.0) {
    discard;
  }

  // The grass: the meadow's tone, its tufts, and blades catching the light,
  // or in shade, among them.
  let tuft = tufts(p);
  // Tufts far off blur together, their light and shade with them.
  // Under the blades the grass is their roots' deep green, so where the
  // ground shows between them it reads as shade.
  // The ground under the blades is in their shade, a little darker than
  // their roots.
  var grass = sward(input.tone, tuft.x, mix(0.55, 1.0, fine)) * root_shade * 0.78;
  if (finest > 0.0) {
    let blade = strokes(p / 0.075, 43u);
    grass *= mix(1.0, mix(0.88, mix(0.85, 1.4, blade.y), blade.x), finest);
  }
  // Gusts pale the grass they bend over.
  grass = mix(grass, grass * vec3f(1.13, 1.12, 1.0) + vec3f(0.015, 0.02, 0.0), gusting * 0.55);

  // Something small every so often: a cell of a grid a fifth of a unit
  // across holds a pebble in the earth, or, rarely, a tiny flower in the
  // grass.
  let speck = speck_at(p / 0.2, 47u, 0.3);
  var petals = 0.0;
  if (speck.kind < 0.0018) {
    let size = 0.15 + 0.09 * fract(speck.kind * 3907.0);
    let soft = max(pixel / 0.2, 0.01);
    let apart = length(speck.offset);
    // Smaller than a pixel, it fades rather than flickers.
    let strength = min(1.0, size * size / (soft * soft));
    petals = (1.0 - smoothstep(size - soft, size + soft, apart)) * strength;
    let heart = (1.0 - smoothstep(size * 0.38 - soft, size * 0.38 + soft, apart)) * strength;
    var flower = flower_white;
    var middle = vec3f(0.95, 0.72, 0.12);
    if (speck.kind < 0.0006) {
      flower = flower_yellow;
      middle = vec3f(0.85, 0.55, 0.08);
    } else if (speck.kind < 0.001) {
      flower = flower_violet;
      middle = vec3f(0.98, 0.9, 0.6);
    }
    grass = mix(grass, mix(flower, middle, heart), petals);
  }

  // Where the grass grows: short of the trodden earth, and out into it
  // only on its tufts, ragged.
  let bare = bareness(r, footprint + input.slow.y);
  let wisps = noise(p * 7.0, 39u);
  // The green ends a little short of where the blades do (grass.wgsl), so
  // at the edge they overhang the earth rather than the ground's green
  // running on past them.
  let cover = (1.0 - bare) - 0.72 + (tuft.x - 0.5) * 0.5 + (wisps - 0.5) * 0.5;
  let grassy = smoothstep(-0.06, 0.06, cover);

  // The earth: mottled, damp and darker in places and toward the grass,
  // dusty and dry where the most feet go, nearest the rock, lumpy, gritty,
  // and strewn with pebbles (nearly a fifth of the speck grid's cells) and,
  // near the rock, crumbs of its salt.
  var earth = vec3f(0.0);
  var earth_tilt = vec2f(0.0);
  var stone = 0.0;
  if (grassy < 1.0) {
    earth = mix(earth_dark, earth_mid, smoothstep(0.3, 0.68, input.mottle));
    earth = mix(earth, earth_dark * 0.85, max(input.slow.z * 0.5, (1.0 - bare) * 0.6));
    // Dustier toward its edge.
    let worn = 0.35 + 0.5 * (1.0 - extent);
    let dry = worn * input.slow.w;
    earth = mix(earth, earth_dust, smoothstep(0.0, 0.7, dry) * 0.85);
    // Its lumps are where the grass would have its tufts.
    earth *= 1.0 + (tuft.x - 0.5) * 0.5 * fine;
    earth_tilt = -tuft.yz * 0.09 * fine;
    if (fine > 0.0) {
      // Grit: specks darker and lighter than the soil.
      let grit = speck_at(p / 0.04, 58u, 0.25);
      let grain = 0.06 + 0.16 * fract(grit.kind * 41.0);
      let speck = (1.0 - smoothstep(grain * 0.6, grain, length(grit.offset))) * fine;
      earth *= 1.0 + select(-0.3, 0.25, grit.kind > 0.7) * speck * step(0.3, abs(grit.kind - 0.4));
    }
    if (speck.kind > 0.82) {
      let pebble = (speck.kind - 0.82) / 0.18;
      let detail = 1.0 - smoothstep(0.12, 0.4, pixel / 0.2);
      let k = fract(pebble * 89.0);
      // Near the rock some are crumbs of its salt, angular; the rest are
      // pebbles, rounded. Each lies its own way.
      let salty = step(fract(pebble * 13.0), worn * 0.7);
      let way = normalize(vec2f(fract(pebble * 7.0), fract(pebble * 19.0)) - 0.49);
      let q = vec2f(dot(speck.offset, way), speck.offset.y * way.x - speck.offset.x * way.y);
      let apart = mix(length(q * vec2f(1.0, 1.35)), max(abs(q.x), abs(q.y) * 1.4), salty);
      let size = mix(0.07 + 0.11 * k, 0.05 + 0.06 * k, salty);
      stone = (1.0 - smoothstep(size - 0.025, size, apart)) * detail;
      let rim = (1.0 - smoothstep(size, size + 0.07, apart)) * detail;
      earth *= 1.0 - 0.4 * (rim - stone);
      let shade = 0.7 + 0.5 * fract(pebble * 53.0);
      let warmth = mix(vec3f(1.0), vec3f(1.1, 0.97, 0.86), fract(pebble * 31.0));
      var color = pebble_color * shade * warmth;
      color = mix(color, salt_crumb * (0.85 + 0.2 * shade), salty);
      earth = mix(earth, color, stone);
      earth_tilt += speck.offset / size * 0.7 * stone;
    }
  }

  // The earth just past the grass is in its shade, darker toward it, so the
  // grass's edge sits in the ground rather than on it.
  earth *= 1.0 - 0.32 * smoothstep(-0.3, 0.0, cover) * (1.0 - grassy);
  // Sparse grass over earth shows the soil darkly through it.
  let fringe = grassy * (1.0 - grassy) * 4.0;
  var albedo = mix(earth, grass, grassy);
  albedo = mix(albedo, albedo * vec3f(0.72, 0.8, 0.66), fringe * 0.45);
  // Salt spilled at the rock's foot: white and sugary, in a ragged band,
  // a few crumbs scattered past its edge.
  let spilled = 1.0 - smoothstep(-0.06, 0.06, r - footprint - spill(p));
  let crumbs = step(0.93, noise(p * 22.0, 79u)) * (1.0 - smoothstep(0.0, 0.6, r - footprint - spill(p)));
  let powder = vec3f(0.96, 0.93, 0.88) * (0.86 + 0.18 * noise(p * 46.0, 77u));
  albedo = mix(albedo, powder, max(spilled, crumbs * 0.8));

  // The surface's tilt: the tufts' in the grass; the lumps' and the
  // pebbles' in the earth.
  let tilt = mix(earth_tilt, -tuft.yz * 0.07, grassy);
  var normal = normalize(vec3f(tilt.x, 1.0, tilt.y));

  // Darker right at the rock's base, the more the closer under it, and in
  // the hollows between tufts.
  let under = 1.0 - smoothstep(0.55, 1.2, r / max(footprint, 0.1));
  let hollow = mix(1.0, 0.78 + 0.22 * smoothstep(0.15, 0.75, tuft.x), grassy * (1.0 - petals));
  var occlusion = (1.0 - 0.5 * under) * hollow;

  let soft = 0.22 * grassy + 0.1;

  if (draw.settings.x < 0.5) {
    return vec4f(albedo * occlusion, extent);
  }
  let to_light = normalize(-scene.light_direction.xyz);
  let sun = sunlit(input.world, vec3f(0.0, 1.0, 0.0));
  // Grass and soil let the light wrap a little round their lumps.
  let diffuse = max((dot(normal, to_light) + soft) / (1.0 + soft), 0.0) * (1.0 - 0.25 * under);
  let ambient = scene.ambient.xyz * (0.8 + 0.2 * normal.y) * occlusion;
  var lit = albedo * (ambient + scene.light_color.xyz * diffuse * sun * mix(1.0, hollow, 0.6));
  // Pebbles and gusting grass catch a little sheen.
  let gloss = stone * 0.1 + grassy * (0.04 + 0.1 * gusting);
  if (gloss > 0.0) {
    let halfway = normalize(to_light + normalize(input.eye - input.world));
    let shine = pow(max(dot(normal, halfway), 0.0), mix(10.0, 24.0, stone)) * gloss * sun;
    lit += scene.light_color.xyz * shine * max(dot(normal, to_light), 0.0);
  }
  return vec4f(lit, extent);
}

