// A connected paper sheet with a thin backing and softly lifted corners.
struct Scene {
  view: mat4x4f, projection: mat4x4f, ambient: vec4f,
  light_direction: vec4f, light_color: vec4f, light_view_projection: mat4x4f,
  shadow: vec4f,
};
struct Parameters { width: f32, depth: f32, seed: f32, unused: f32 };
struct Draw { model: mat4x4f, normal: mat4x4f, color: vec4f, settings: vec4f, parameters: Parameters };
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var paper: texture_2d<f32>;
@group(1) @binding(2) var paper_sampler: sampler;
struct Input { @location(0) position: vec3f, @location(1) normal: vec3f, @location(2) uv: vec2f };
struct Output { @builtin(position) position: vec4f, @location(0) uv: vec2f, @location(1) world: vec3f, @location(2) normal: vec3f, @location(3) side: f32 };
fn corner(uv:vec2f,at:vec2f)->f32 { return pow(max(0.0,1.0-length((uv-at)/vec2f(.27))),2.0); }
fn height(uv:vec2f)->f32 {
  let seed=draw.parameters.seed;
  let a=.11+.05*sin(seed*13.1);
  let b=.16+.055*cos(seed*7.3);
  let wrinkles=.005*sin(uv.x*23.0+seed)*sin(uv.y*17.0+seed*.4);
  return .215+wrinkles+corner(uv,vec2f(0,0))*a+corner(uv,vec2f(1,1))*b+corner(uv,vec2f(0,1))*.035;
}
@vertex fn vertex(v:Input)->Output {
  let p=draw.parameters;
  let e=.002;
  let dx=(height(v.uv+vec2f(e,0))-height(v.uv-vec2f(e,0)))/(2.0*e*p.width);
  let dz=(height(v.uv+vec2f(0,e))-height(v.uv-vec2f(0,e)))/(2.0*e*p.depth);
  let local=vec3f((v.uv.x-.5)*p.width,height(v.uv)+v.position.y,(v.uv.y-.5)*p.depth);
  let world=draw.model*vec4f(local,1);
  let normal=(draw.normal*vec4f(normalize(vec3f(-dx,1,-dz)),0)).xyz;
  return Output(scene.projection*scene.view*world,v.uv,world.xyz,normal,v.normal.y);
}
@fragment fn fragment(v:Output)->@location(0) vec4f {
  let seed=draw.parameters.seed;
  let coords=v.uv+vec2f(fract(seed*.31),fract(seed*.73));
  let tiled=1.0-abs(fract(coords*.5)*2.0-1.0);
  var albedo=textureSample(paper,paper_sampler,tiled).rgb;
  // Crisp ink, fibrous pigment, and a pale cut edge make it read as paper.
  let border=min(min(v.uv.x,1.0-v.uv.x),min(v.uv.y,1.0-v.uv.y));
  albedo=mix(albedo,vec3f(.83,.89,.9),1.0-smoothstep(.002,.006,border));
  if(v.side<0.0) { albedo=vec3f(.59,.69,.72); }
  let n=normalize(v.normal)*select(-1.0,1.0,v.side>=0.0);
  let diffuse=max(0.0,dot(n,normalize(-scene.light_direction.xyz)));
  var shadow=1.0;
  if(scene.shadow.x>.5) {
    let clip=scene.light_view_projection*vec4f(v.world+normalize(v.normal)*scene.shadow.z,1);
    let ndc=clip.xyz/clip.w; let at=vec2f(ndc.x*.5+.5,.5-ndc.y*.5);
    if(all(at>=vec2f(0))&&all(at<=vec2f(1))&&ndc.z<1) { shadow=textureSampleCompareLevel(shadow_map,shadow_sampler,at,ndc.z-.0004); }
  }
  let light=scene.ambient.rgb+scene.light_color.rgb*(.18+.82*diffuse)*shadow;
  return vec4f(albedo*light,1);
}

