// Thin, rough paper and wrinkled masking tape. RGB is the printed stock;
// alpha is fiber height. attributes.x distinguishes paper, tape, and shadow.
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
  zenith: vec4f,
  horizon: vec4f,
  ground: vec4f,
  eye: vec4f,
};
struct Parameters {
  hovered: f32,
  selected: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var base_color: texture_2d<f32>;
@group(1) @binding(2) var base_sampler: sampler;
struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
  @location(8) attributes: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) normal: vec3f,
  @location(1) world: vec3f,
  @location(2) uv: vec2f,
  @location(3) attributes: vec2f,
};
@vertex fn vertex(input: VertexInput) -> VertexOutput {
  let world = draw.model * vec4f(input.position, 1.0);
  var output: VertexOutput;
  output.position = scene.projection * scene.view * world;
  output.normal = (draw.normal * vec4f(input.normal, 0.0)).xyz;
  output.world = world.xyz;
  output.uv = input.uv;
  output.attributes = input.attributes;
  return output;
}
@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let stock = textureSample(base_color, base_sampler, input.uv);
  let n = normalize(input.normal);
  let dx = dpdx(input.world);
  let dy = dpdy(input.world);
  let tx = cross(dy, n);
  let ty = cross(n, dx);
  let det = dot(dx, tx);
  let gradient = dpdx(stock.a) * tx + dpdy(stock.a) * ty;
  let normal = normalize(n - 0.004 * gradient / max(abs(det), 1e-8) * sign(det));
  if (input.attributes.x > 1.5) {
    let edge = abs(input.uv - vec2f(0.5));
    let coverage = (1.0 - smoothstep(0.34, 0.5, edge.x)) * (1.0 - smoothstep(0.39, 0.5, edge.y));
    return vec4f(0.0, 0.0, 0.0, coverage * 0.23);
  }
  let tape = step(0.5, input.attributes.x);
  let light = normalize(-scene.light_direction.xyz);
  let eye = normalize(scene.eye.xyz - input.world);
  let ink = 1.0 - smoothstep(0.04, 0.35, dot(stock.rgb, vec3f(0.3, 0.6, 0.1)));
  let albedo = mix(stock.rgb, stock.rgb * vec3f(0.45, 1.05, 0.65), ink * draw.parameters.selected * 0.75);
  let ambient = scene.ambient.rgb * (0.85 + 0.15 * normal.y);
  let diffuse = albedo * (ambient + scene.light_color.xyz * max(dot(normal, light), 0.0) + 0.14);
  let sheen = pow(max(dot(normal, normalize(light + eye)), 0.0), 32.0) * tape * 0.08;
  let lifted = 1.0 + draw.parameters.hovered * 0.035;
  return vec4f((diffuse * input.attributes.y + scene.light_color.xyz * sheen) * lifted, 1.0);
}

