// The tucked-away phone reads as a clean icon. Opening it restores the
// palette's baked shelter, glossy housing and metallic reflections.
struct Scene {
  view: mat4x4f, projection: mat4x4f, ambient: vec4f,
  light_direction: vec4f, light_color: vec4f, light_view_projection: mat4x4f,
  shadow: vec4f, zenith: vec4f, horizon: vec4f, ground: vec4f, eye: vec4f,
};
struct Parameters { gloss: f32, metal: f32, glow: f32, realism: f32 };
struct Draw {
  model: mat4x4f, normal: mat4x4f, color: vec4f, settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var palette: texture_2d<f32>;
@group(1) @binding(2) var palette_sampler: sampler;
struct VertexInput {
  @location(0) position: vec3f, @location(1) normal: vec3f, @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) normal: vec3f, @location(1) world: vec3f, @location(2) uv: vec2f,
};
@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let world = draw.model * vec4f(input.position, 1.0);
  output.position = scene.projection * scene.view * world;
  output.normal = (draw.normal * vec4f(input.normal, 0.0)).xyz;
  output.world = world.xyz;
  output.uv = input.uv;
  return output;
}
@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let finish = clamp(draw.parameters.realism, 0.0, 1.0);
  // Every palette row is one source material; its columns store occlusion.
  // Flatten the columns while tucked down, keeping dial lettering intact.
  let clean = textureSample(palette, palette_sampler, vec2f(0.9, input.uv.y)).rgb;
  let shaded = textureSample(palette, palette_sampler, input.uv).rgb;
  let albedo = mix(clean, shaded, finish) * draw.color.rgb;
  let normal = normalize(input.normal);
  let light = normalize(-scene.light_direction.xyz);
  let eye = normalize(scene.eye.xyz - input.world);
  let flat = albedo * (0.78 + 0.22 * max(dot(normal, light), 0.0));
  let diffuse = albedo * (scene.ambient.rgb + scene.light_color.rgb * max(dot(normal, light), 0.0)
    + vec3f(draw.parameters.glow));
  let halfway = normalize(light + eye);
  // Broad filtered highlights avoid the tiny, sparkling highlights that
  // made the phone look grainy at the bottom edge.
  let glint = pow(max(dot(normal, halfway), 0.0), mix(12.0, 48.0, draw.parameters.gloss));
  let reflected = mix(scene.horizon.rgb, scene.zenith.rgb,
    clamp(reflect(-eye, normal).y * 0.5 + 0.5, 0.0, 1.0));
  let metal = draw.parameters.metal;
  let lit = diffuse * (1.0 - metal * 0.45)
    + glint * scene.light_color.rgb * mix(vec3f(0.14), albedo, metal)
    + reflected * albedo * metal * 0.35;
  return vec4f(mix(flat, lit, finish), draw.color.a);
}

