fn turned(point: vec3f) -> vec3f {
  let pitch = draw.parameters.pitch;
  let roll = draw.parameters.roll;
  let p = vec3f(point.x, cos(pitch) * point.y - sin(pitch) * point.z,
    sin(pitch) * point.y + cos(pitch) * point.z);
  return vec3f(cos(roll) * p.x - sin(roll) * p.y,
    sin(roll) * p.x + cos(roll) * p.y, p.z);
}

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  let grip = draw.grip.xyz;
  let held = grip + turned(input.position - grip) + vec3f(0.0, draw.parameters.rise, 0.0);
  let point = mix(input.position, held, input.uv.x);
  let normal = normalize(mix(input.normal, turned(input.normal), input.uv.x));
  let world = draw.model * vec4f(point, 1.0);
  var output: VertexOutput;
  output.position = scene.projection * scene.view * world;
  output.normal = (draw.normal * vec4f(normal, 0.0)).xyz;
  output.world = world.xyz;
  output.shelter = input.uv.y;
  return output;
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let normal = normalize(input.normal);
  let light = normalize(-scene.light_direction.xyz);
  let eye = normalize(scene.eye.xyz - input.world);
  let diffuse = scene.ambient.xyz + scene.light_color.xyz * max(dot(normal, light), 0.0);
  let highlight = pow(max(dot(normal, normalize(light + eye)), 0.0), 24.0) * 0.035;
  let real = (draw.color.rgb * diffuse + scene.light_color.xyz * highlight) * input.shelter;
  let color = mix(draw.color.rgb * 0.9, real, draw.parameters.realism);
  return vec4f(color, draw.color.a);
}

