// A broad soft shadow separates the phone from the world without a backing disc.
struct Screen { size: vec4f };
struct Parameters { unused0: f32, unused1: f32, unused2: f32, unused3: f32 };
struct Sprite { rect: vec4f, uv: vec4f, color: vec4f, parameters: Parameters };
@group(0) @binding(0) var<uniform> screen: Screen;
@group(0) @binding(1) var<storage, read> sprites: array<Sprite>;
struct Corner {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f, @location(1) color: vec4f,
};
@vertex fn vertex(@builtin(vertex_index) vertex: u32, @builtin(instance_index) index: u32) -> Corner {
  let sprite = sprites[index];
  let corner = array<vec2f, 6>(vec2f(0,0), vec2f(1,0), vec2f(0,1), vec2f(0,1), vec2f(1,0), vec2f(1,1))[vertex];
  let pixel = sprite.rect.xy + corner * sprite.rect.zw;
  var output: Corner;
  output.position = vec4f(pixel.x / screen.size.x * 2.0 - 1.0, 1.0 - pixel.y / screen.size.y * 2.0, 0.0, 1.0);
  output.uv = corner;
  output.color = sprite.color;
  return output;
}
@fragment fn fragment(input: Corner) -> @location(0) vec4f {
  let radius = length((input.uv - vec2f(0.5)) * 2.0);
  let shadow = (1.0 - smoothstep(0.38, 1.0, radius)) * exp(-radius * radius * 0.8);
  return vec4f(input.color.rgb, shadow * input.color.a);
}

