struct Scene { view: mat4x4f, projection: mat4x4f };
struct Parameters { inner: f32, angle: f32, arc: f32, mode: f32 };
struct Draw { model: mat4x4f, normal: mat4x4f, color: vec4f, settings: vec4f, parameters: Parameters };
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var paper: texture_2d<f32>;
@group(1) @binding(2) var paper_sampler: sampler;
struct Input { @location(0) position: vec3f, @location(1) normal: vec3f, @location(2) uv: vec2f };
struct Output { @builtin(position) position: vec4f, @location(0) uv: vec2f, @location(1) world: vec2f };
@vertex fn vertex(v:Input)->Output {
  let p=draw.parameters;
  let r=p.inner+mix(.025,.975,v.uv.y);
  let a=p.angle+p.arc*mix(.025,.975,v.uv.x);
  let at=draw.model*vec4f(cos(a)*r,.19,sin(a)*r,1);
  return Output(scene.projection*scene.view*at,v.uv,at.xz);
}
@fragment fn fragment(v:Output)->@location(0) vec4f {
  let edge=min(min(v.uv.x,1.0-v.uv.x),min(v.uv.y,1.0-v.uv.y));
  let border=1.0-smoothstep(.018,.029,edge);
  let mode=draw.parameters.mode;
  var color=select(vec3f(.24,.65,.92),vec3f(.95,.22,.2),mode<0.0);
  var alpha=.24+border*.45;
  if(mode>1.5) {
    let uv=1.0-abs(fract(v.world*.5)*2.0-1.0);
    color=textureSample(paper,paper_sampler,uv).rgb;
    color=mix(color,vec3f(.74,.91,1),border*.8);
    alpha=.95;
  }
  return vec4f(color,alpha);
}

files.src/assets/pointer.wgsl:
// The pointer: glossy green, like polished glass or a cut gem. Light wraps
// softly round it so it reads from any side, a tight highlight glints on its
// facets, a pale mint rim lights its edges against the scene, and it glows a
// little of its own so it shows at night. Its shadow falls as any lit
// surface's does.
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  settings: vec4f,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) normal: vec3f,
  @location(1) world: vec3f,
};

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let world = draw.model * vec4f(input.position, 1.0);
  output.position = scene.projection * scene.view * world;
  output.normal = (draw.normal * vec4f(input.normal, 0.0)).xyz;
  output.world = world.xyz;
  return output;
}

const rim_color = vec3f(0.75, 1.0, 0.82);

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let normal = normalize(input.normal);
  let to_light = normalize(-scene.light_direction.xyz);
  let turn = mat3x3f(scene.view[0].xyz, scene.view[1].xyz, scene.view[2].xyz);
  let eye = -(transpose(turn) * scene.view[3].xyz);
  let to_eye = normalize(eye - input.world);
  let base = draw.color.rgb;
  let wrapped = dot(normal, to_light) * 0.5 + 0.5;
  let halfway = normalize(to_light + to_eye);
  let glint = pow(max(dot(normal, halfway), 0.0), 90.0) * 1.4;
  let sheen = pow(max(dot(normal, halfway), 0.0), 12.0) * 0.18;
  let facing = max(dot(normal, to_eye), 0.0);
  let rim = pow(1.0 - facing, 3.0);
  let light = scene.ambient.xyz + scene.light_color.xyz * wrapped * wrapped;
  let lit = base * (light * 0.85 + 0.3) + scene.light_color.xyz * (glint + sheen) + rim_color * rim * 0.55;
  return vec4f(lit, draw.color.a);
}

