// A flat box in the sprite's color whose corners are rounded, `radius`
// pixels, its edge smoothed over a pixel: the dev tools' panels, rows and
// bars (devtools/), as a stylesheet's border-radius has them. No texture.
struct Parameters {
  radius: f32,
};
struct Screen {
  size: vec4f,
};
struct Sprite {
  rect: vec4f,
  uv: vec4f,
  color: vec4f,
  parameters: vec4f,
};
@group(0) @binding(0) var<uniform> screen: Screen;
@group(0) @binding(1) var<storage, read> sprites: array<Sprite>;

struct Corner {
  @builtin(position) position: vec4f,
  // Pixels from the sprite's top left.
  @location(0) local: vec2f,
  @location(1) @interpolate(flat) size: vec2f,
  @location(2) @interpolate(flat) color: vec4f,
  @location(3) @interpolate(flat) parameters: vec4f,
};

@vertex fn vertex(@builtin(vertex_index) vertex: u32, @builtin(instance_index) index: u32) -> Corner {
  let sprite = sprites[index];
  let corner = array<vec2f, 6>(vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(0.0, 1.0), vec2f(0.0, 1.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0))[vertex];
  let pixel = sprite.rect.xy + corner * sprite.rect.zw;
  var output: Corner;
  output.position = vec4f(pixel.x / screen.size.x * 2.0 - 1.0, 1.0 - pixel.y / screen.size.y * 2.0, 0.0, 1.0);
  output.local = corner * sprite.rect.zw;
  output.size = sprite.rect.zw;
  output.color = sprite.color;
  output.parameters = sprite.parameters;
  return output;
}

// The signed distance in pixels from `p` to a box of `half` its size round
// `centre` with corners `radius` round, negative inside.
fn rounded_box(p: vec2f, centre: vec2f, half: vec2f, radius: f32) -> f32 {
  let q = abs(p - centre) - (half - radius);
  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - radius;
}

@fragment fn fragment(corner: Corner) -> @location(0) vec4f {
  let half = corner.size * 0.5;
  let radius = clamp(corner.parameters.x, 0.0, min(half.x, half.y));
  let distance = rounded_box(corner.local, half, half, radius);
  let covered = clamp(0.5 - distance, 0.0, 1.0);
  return vec4f(corner.color.rgb, corner.color.a * covered);
}

files.src/assets/salt.wgsl:
// Rock salt: the gnorp rock and the bricks knocked out of it. A crystal
// texture (color, with gloss in alpha) and its relief (a normal map) are
// projected onto the surface along the object's three axes, in its own space
// scaled to world size: the crystals keep one size on rocks of any shape and
// stick to the surface as it moves. The mesh's palette swatch, by its UVs,
// tints them, so the recesses and streaks the model paints stay.
//
// Salt is lit as salt is: creamy and bright, the light wrapping round past
// the shadow line and scattering a little into its shade, glowing warm when
// the sun is behind it, with grains that glint as the view moves. A few of
// the rock's swatches are not salt (models/rock/rock.py): clear crystals,
// glassy, with a bright rim and a glow inside; pebbles, plain stone; and
// the succulents' leaves and bulbs, their own colors, untouched by the salt.
//
// Strikes dent it. The draw's extra data holds up to eight, two vectors each:
// where the strike's line starts and how strongly its dent shows (1, fading
// to 0), then the way the line runs (its heading about the vertical and its
// pitch), the dent's radius and the pattern its chips break in. The first surface
// facing the strike, where its line meets it, sinks in a shallow bowl with a
// raised rim, its salt shattered into angular chips that lean every which way
// and catch the light apart, white fracture seams between them, crushed and
// matte, a few chips knocked out. The edge follows whole chips, so it is
// ragged. As it fades it all fades together; it never shrinks. Only the
// shading changes: the mesh keeps its shape.
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  // x: 1 with a shadow map, y: its texel in texture coordinates, z: how far
  // off the surface to read it, in world units.
  shadow: vec4f,
  // The sky the scene sits under (the frame's): its colors overhead, at the
  // horizon and below it; and where the eye is.
  zenith: vec4f,
  horizon: vec4f,
  ground: vec4f,
  eye: vec4f,
};
// What a draw passes (src/rock.blot): how much of it is clear salt in
// patches, 0 to 1.
struct Parameters {
  clear: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  // x: lit, z: 1 once the relief has loaded, w: once the crystals have.
  settings: vec4f,
  parameters: Parameters,
  extra: array<vec4f, 16>,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var palette: texture_2d<f32>;
@group(1) @binding(2) var surface_sampler: sampler;
@group(1) @binding(3) var relief: texture_2d<f32>;
@group(1) @binding(4) var crystals: texture_2d<f32>;

// World units one repeat of the crystal texture covers.
const tile = 4.0;
// How much more the texture's own light and shade varies over a few repeats,
// so the repeats do not show.
const variation = 0.18;
// How strongly the relief tilts the surface, and how much of the palette's
// shading shows: the model's swatches were painted for flat lighting, and the
// relief and the scene's light now do most of that work.
const relief_strength = 0.25;
const palette_strength = 0.9;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
  // The rock's smooth normal, packed (models/rock/tessellate.py); zero for
  // meshes without it.
  @location(8) soft_normal: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) normal: vec3f,
  @location(1) uv: vec2f,
  @location(2) world: vec3f,
  // The object's own position and normal, scaled to world size.
  @location(3) local: vec3f,
  @location(4) local_normal: vec3f,
  // Where the surface was before the strikes pushed it in.
  @location(5) rest: vec3f,
};

// The normal packed in two numbers (octahedral), or none.
fn unpacked(packed: vec2f) -> vec3f {
  var n = vec3f(packed, 1.0 - abs(packed.x) - abs(packed.y));
  if (n.z < 0.0) {
    n = vec3f((1.0 - abs(n.yx)) * select(vec2f(-1.0), vec2f(1.0), n.xy >= vec2f(0.0)), n.z);
  }
  return normalize(n);
}

fn scale_of(model: mat4x4f) -> vec3f {
  return vec3f(length(model[0].xyz), length(model[1].xyz), length(model[2].xyz));
}

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let world = draw.model * vec4f(input.position, 1.0);
  let scale = scale_of(draw.model);
  // Where strikes chipped the rock, it is pushed in: for each copy of a
  // vertex alike, by the rock's smooth normal there.
  var moved = world.xyz;
  if (any(input.soft_normal != vec2f(0.0))) {
    moved = pushed(world.xyz, normalize((draw.normal * vec4f(unpacked(input.soft_normal), 0.0)).xyz));
  }
  output.position = scene.projection * scene.view * vec4f(moved, 1.0);
  output.normal = (draw.normal * vec4f(input.normal, 0.0)).xyz;
  output.uv = input.uv;
  output.world = moved;
  output.rest = world.xyz;
  output.local = input.position * scale;
  output.local_normal = input.normal / scale;
  return output;
}

// How much sunlight reaches `world`, as in scene.wgsl.
fn sunlit(world: vec3f, normal: vec3f) -> f32 {
  if (scene.shadow.x < 0.5) {
    return 1.0;
  }
  let clip = scene.light_view_projection * vec4f(world + normal * scene.shadow.z, 1.0);
  let ndc = clip.xyz / clip.w;
  let uv = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
  if (any(uv < vec2f(0.0)) || any(uv > vec2f(1.0)) || ndc.z > 1.0) {
    return 1.0;
  }
  var light = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      light += textureSampleCompareLevel(shadow_map, shadow_sampler,
        uv + vec2f(f32(x), f32(y)) * scene.shadow.y, ndc.z - 0.0004);
    }
  }
  return light / 9.0;
}


fn scatter(p: vec2f, seed: f32) -> f32 {
  return fract(sin(dot(p, vec2f(12.9898, 78.233)) + seed * 7.13) * 43758.5453);
}

// Smooth noise over space, 0..1, for where the salt is clear.
fn hash3(cell: vec3f) -> f32 {
  return scatter(cell.xy + cell.z * vec2f(17.31, 7.17), 61.0);
}
fn noise3(p: vec3f) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(hash3(i), hash3(i + vec3f(1.0, 0.0, 0.0)), u.x);
  let b = mix(hash3(i + vec3f(0.0, 1.0, 0.0)), hash3(i + vec3f(1.0, 1.0, 0.0)), u.x);
  let c = mix(hash3(i + vec3f(0.0, 0.0, 1.0)), hash3(i + vec3f(1.0, 0.0, 1.0)), u.x);
  let d = mix(hash3(i + vec3f(0.0, 1.0, 1.0)), hash3(i + vec3f(1.0, 1.0, 1.0)), u.x);
  return mix(mix(a, b, u.y), mix(c, d, u.y), u.z);
}

// How deep into clear salt the eye sees, in world units.
const clear_depth = 0.45;

// A strike's scar: a chip knocked out, as a chisel or a flint knapper leaves
// one. Five to seven flat facets, each a plane cutting the surface along one
// side of a ragged polygon round the strike, slope in until they meet a small
// flat floor a little off the middle, `scar_floor` of the radius deep; the
// scar is the highest of them at each point, so they meet in straight ridges.
// The vertex stage pushes the rock in to it and the fragment stage shades it,
// both from here, at `p`, the point's place across the strike's line: how
// deep it goes there, the facet's rise outward (for the normal), how far the
// point is outside the outline (negative inside), how far from a ridge or the
// floor's edge, and whether it is on the floor.
const scar_floor = 0.32;
struct Scar {
  depth: f32,
  rise: vec2f,
  outside: f32,
  ridge: f32,
  floor: f32,
};
fn scar(p: vec2f, radius: f32, seed: f32) -> Scar {
  let count = 5u + u32(scatter(vec2f(seed, 2.0), seed) * 3.0);
  let turn = scatter(vec2f(seed, 1.0), seed) * 6.2831853;
  let off = scatter(vec2f(seed, 8.0), seed) * 6.2831853;
  let q = p - vec2f(cos(off), sin(off)) * radius * 0.16;
  let deepest = radius * scar_floor;
  var top = -1e9;
  var second = -1e9;
  var rise = vec2f(0.0);
  var steep = 1.0;
  for (var index = 0u; index < 7u; index++) {
    if (index >= count) {
      break;
    }
    let f = f32(index);
    let angle = (f + 0.4 * (scatter(vec2f(f, 9.0), seed) - 0.5)) / f32(count) * 6.2831853 + turn;
    let way = vec2f(cos(angle), sin(angle));
    let reach = radius * (0.62 + 0.42 * scatter(vec2f(f, 3.0), seed));
    let slope = deepest / max(reach - radius * (0.16 + 0.12 * scatter(vec2f(f, 4.0), seed)), radius * 0.2);
    let height = slope * (dot(q, way) - reach);
    if (height > top) {
      second = top;
      top = height;
      rise = way * slope;
      steep = slope;
    } else if (height > second) {
      second = height;
    }
  }
  let on_floor = top < -deepest;
  var found: Scar;
  found.depth = clamp(-top, 0.0, deepest);
  found.rise = select(rise, vec2f(0.0), on_floor);
  found.outside = top / steep;
  found.ridge = select(min((top - second) / steep, abs(top + deepest) / steep), abs(top + deepest) / steep, on_floor);
  found.floor = select(0.0, 1.0, on_floor);
  return found;
}

// Strike `index` of the draw's extra vectors: where its line starts, how
// strongly its scar shows (1, healing to 0), the way the line runs and two
// ways across it, the scar's radius and its pattern.
struct Strike {
  start: vec3f,
  strength: f32,
  toward: vec3f,
  side: vec3f,
  other: vec3f,
  radius: f32,
  seed: f32,
};
fn strike_at(index: u32) -> Strike {
  let start = draw.extra[index * 2u];
  let heading = draw.extra[index * 2u + 1u];
  let toward = vec3f(cos(heading.y) * sin(heading.x), sin(heading.y), cos(heading.y) * cos(heading.x));
  let reference = select(vec3f(0.0, 1.0, 0.0), vec3f(1.0, 0.0, 0.0), abs(toward.y) > 0.95);
  let side = normalize(cross(toward, reference));
  return Strike(start.xyz, start.w, toward, side, cross(side, toward), heading.z, heading.w);
}

// How much of a strike reaches the surface at `world` facing `surface`: the
// surfaces facing it, ahead of where its line starts, within reach of it.
fn reached(strike: Strike, world: vec3f, surface: vec3f) -> f32 {
  if (strike.strength <= 0.0 || strike.radius <= 0.0) {
    return 0.0;
  }
  let offset = world - strike.start;
  let facing = smoothstep(-0.1, -0.3, dot(surface, strike.toward));
  return facing * step(-0.5, dot(offset, strike.toward)) * strike.strength;
}

// The point's place across the strike's line.
fn across(strike: Strike, world: vec3f) -> vec2f {
  let offset = world - strike.start;
  let off_line = offset - strike.toward * dot(offset, strike.toward);
  return vec2f(dot(off_line, strike.side), dot(off_line, strike.other));
}

// `world` pushed in where the strikes chipped the rock; `soft_normal` is the
// rock's smooth normal there, alike for every copy of a vertex, so the
// surface moves whole.
fn pushed(world: vec3f, soft_normal: vec3f) -> vec3f {
  var moved = world;
  for (var index = 0u; index < 8u; index++) {
    let strike = strike_at(index);
    let reach = reached(strike, world, soft_normal);
    if (reach <= 0.0) {
      continue;
    }
    let p = across(strike, world);
    if (length(p) > strike.radius * 1.2) {
      continue;
    }
    moved += strike.toward * scar(p, strike.radius, strike.seed).depth * reach;
  }
  return moved;
}

// What the strikes do at `world` on a surface facing `surface`: the slope
// their scars add (to subtract from the normal), how crushed the salt is
// there (the powder round a scar, its lip and the ridges between its
// facets), how much of it is freshly broken (the facets, clean glassy salt
// from inside the rock) and how much light the scars shut out. `pixel` is a
// screen pixel's width there, to keep the edges crisp but smooth.
struct Damage {
  slope: vec3f,
  crushed: f32,
  broken: f32,
  hollow: f32,
};
fn damage(world: vec3f, surface: vec3f, pixel: f32) -> Damage {
  var found = Damage(vec3f(0.0), 0.0, 0.0, 0.0);
  for (var index = 0u; index < 8u; index++) {
    let strike = strike_at(index);
    let reach = reached(strike, world, surface);
    if (reach <= 0.0) {
      continue;
    }
    let p = across(strike, world);
    let radius = strike.radius;
    if (length(p) > radius * 1.5) {
      continue;
    }
    let cut = scar(p, radius, strike.seed);
    let blur = max(pixel * 1.2, radius * 0.012);
    let inside = 1.0 - smoothstep(-blur, blur, cut.outside);
    found.slope += (strike.side * cut.rise.x + strike.other * cut.rise.y) * inside * reach;
    // Fine bright ridges where the facets meet, and a crisp lip round the
    // outline; powdered salt speckled round it, thinning away.
    let ridge = 1.0 - smoothstep(0.0, blur * 1.5, cut.ridge);
    let lip = 1.0 - smoothstep(0.0, blur * 2.0, abs(cut.outside));
    let grain = floor(p / max(radius * 0.05, pixel * 1.5));
    let powder = step(0.55, scatter(grain, strike.seed + 7.0)) * (1.0 - smoothstep(0.0, radius * 0.4, cut.outside)) *
      step(0.0, cut.outside);
    found.crushed = max(found.crushed, max(lip * 0.8, max(ridge * inside * 0.5, powder * 0.65)) * reach);
    found.broken = max(found.broken, inside * reach);
    found.hollow = max(found.hollow, inside * cut.depth / (radius * scar_floor) * 0.3 * reach);
  }
  return found;
}

// The relief at `uv`: a tangent-space normal whose x runs along u and y
// against v (up the image), from its two stored components.
fn bump(uv: vec2f) -> vec3f {
  let xy = (textureSample(relief, surface_sampler, uv).rg * 2.0 - 1.0) * relief_strength;
  return vec3f(xy, sqrt(max(1.0 - dot(xy, xy), 0.0)));
}

// What a palette swatch is, by its index (the palette is 8 by 8 swatches):
// salt, or else a clear crystal (9, 10), a pebble (11, 12), part of a plant
// (13 to 15) or something plain, not salt at all, from 16 on: a doorway's
// dark, wood, cloth, clay. The bricks' palette stops at 8; the rock's and
// the buildings' (models/rock/rock.py, models/buildings/buildings.py) go on.
const salt_kind = 0u;
const crystal_kind = 1u;
const pebble_kind = 2u;
const plant_kind = 3u;
const plain_kind = 4u;
// The palette swatch at `uv`. Palette meshes sample a swatch at its middle;
// anything else, say a mesh whose UVs run across its faces, is salt (0).
fn swatch_of(uv: vec2f) -> u32 {
  let within = fract(uv * 8.0) - 0.5;
  if (any(abs(within) > vec2f(0.1))) {
    return 0u;
  }
  let cell = vec2u(clamp(floor(uv * 8.0), vec2f(0.0), vec2f(7.0)));
  return cell.y * 8u + cell.x;
}

fn kind_of(uv: vec2f) -> u32 {
  let index = swatch_of(uv);
  if (index == 9u || index == 10u) {
    return crystal_kind;
  }
  if (index == 11u || index == 12u) {
    return pebble_kind;
  }
  if (index >= 13u && index <= 15u) {
    return plant_kind;
  }
  if (index >= 16u) {
    return plain_kind;
  }
  return salt_kind;
}

// How a plain swatch takes the light (the buildings' palette,
// models/buildings/plaster.py): how rough it is, how much of a metal and how
// much light it gives off. Lanterns and lit lamps glow past white, and bloom;
// iron shines, worn bright on a rail's top; the lighthouse's red is glossy
// paint; cloth is matte; wood, stone, earth and the rest are rough.
fn finish_of(index: u32) -> vec3f {
  if (index == 27u || index == 46u) {
    return vec3f(0.5, 0.0, 3.0);
  }
  if (index >= 29u && index <= 31u) {
    return vec3f(select(0.45, 0.28, index == 31u), 0.85, 0.0);
  }
  if (index == 32u || index == 33u) {
    return vec3f(0.75, 0.3, 0.0);
  }
  if (index == 44u || index == 45u) {
    return vec3f(0.32, 0.0, 0.0);
  }
  if (index == 21u || index == 22u) {
    return vec3f(0.92, 0.0, 0.0);
  }
  if (index == 23u || index == 24u) {
    return vec3f(0.6, 0.0, 0.0);
  }
  if (index >= 13u && index <= 15u) {
    return vec3f(0.55, 0.0, 0.0);
  }
  return vec3f(0.82, 0.0, 0.0);
}

// Light from all round as a surface facing `normal` takes it: the sky's,
// more from above and tinted by it, and a little bounced off the ground.
fn hemisphere(normal: vec3f) -> vec3f {
  let sky_tint = mix(vec3f(1.0), hue(scene.zenith.rgb), 0.25);
  let ground_tint = mix(vec3f(1.0), hue(scene.ground.rgb), 0.4);
  return scene.ambient.xyz * mix(ground_tint * 0.6, sky_tint * 1.05, normal.y * 0.5 + 0.5);
}

// A color's hue at the brightness of white, or white for black.
fn hue(color: vec3f) -> vec3f {
  let luma = dot(color, vec3f(0.299, 0.587, 0.114));
  return select(vec3f(1.0), color / max(luma, 0.001), luma > 0.001);
}

// The sky along `direction`, as the sky pass paints it, blurred toward its
// average as a surface roughens.
fn sky_seen(direction: vec3f, roughness: f32) -> vec3f {
  let up = direction.y;
  var color = mix(scene.horizon.rgb, scene.zenith.rgb, sqrt(clamp(up, 0.0, 1.0)));
  color = mix(color, scene.ground.rgb, smoothstep(0.0, 0.3, -up));
  let average = (scene.horizon.rgb * 2.0 + scene.zenith.rgb + scene.ground.rgb) * 0.25;
  return mix(color, average, roughness * roughness);
}

// How much light a surface mirrors `cosine` off its normal (Schlick): more at
// a grazing angle, if less the rougher it is.
fn fresnel(f0: vec3f, cosine: f32, roughness: f32) -> vec3f {
  return f0 + (max(vec3f(1.0 - roughness), f0) - f0) * pow(1.0 - clamp(cosine, 0.0, 1.0), 5.0);
}

// The sun's highlight off a surface of `roughness`, per unit of its light
// and before Fresnel (GGX, with Smith's shadowing), times the light's cosine.
fn highlight(normal: vec3f, to_light: vec3f, to_eye: vec3f, roughness: f32) -> f32 {
  let halfway = normalize(to_light + to_eye);
  let nl = max(dot(normal, to_light), 0.0);
  let nv = max(dot(normal, to_eye), 0.001);
  let nh = max(dot(normal, halfway), 0.0);
  let a = roughness * roughness;
  let a2 = a * a;
  let d = nh * nh * (a2 - 1.0) + 1.0;
  let k = (roughness + 1.0) * (roughness + 1.0) / 8.0;
  let visibility = 1.0 / ((nl * (1.0 - k) + k) * (nv * (1.0 - k) + k) * 4.0);
  return a2 / (3.14159265 * d * d) * visibility * nl;
}

// What a surface mirrors: the sun's highlight, where `sun` of it reaches,
// and the sky. A metal (`metal` 1) mirrors in its own color; anything else
// a little, 4% head on, more at a grazing angle.
fn mirrored(albedo: vec3f, normal: vec3f, to_light: vec3f, to_eye: vec3f, roughness: f32, metal: f32, sun: f32) -> vec3f {
  let f0 = mix(vec3f(0.04), albedo, metal);
  let halfway = normalize(to_light + to_eye);
  let glint = highlight(normal, to_light, to_eye, roughness) * fresnel(f0, dot(halfway, to_eye), 0.0) * scene.light_color.xyz * sun;
  let sky = sky_seen(reflect(-to_eye, normal), roughness) * fresnel(f0, dot(normal, to_eye), roughness);
  return glint + sky;
}

// Grains glinting at `local` (object space, world-sized) on a surface facing
// `n` there, lit along `halfway`: a grain in some of the cells of a grid,
// each its own facet, flashing when it mirrors the light to the eye. The
// cells are a few screen pixels across wherever the salt is, so the glints
// are always about a pixel or two, near or far, never smaller.
fn glints(local: vec3f, n: vec3f, normal: vec3f, halfway: vec3f, pixel: f32) -> f32 {
  let glint_cell = max(0.03, pixel * 3.0);
  // On the plane the surface faces most.
  let a = abs(n);
  var q = local.xy;
  if (a.x >= a.y && a.x >= a.z) {
    q = local.zy;
  } else if (a.y >= a.z) {
    q = local.xz;
  }
  let g = q / glint_cell;
  let cell = floor(g);
  let luck = vec3f(scatter(cell, 31.0), scatter(cell + 7.1, 31.0), scatter(cell + 13.7, 31.0));
  let centre = cell + 0.2 + 0.6 * luck.xy;
  let grain = 1.0 - smoothstep(0.15, 0.35, length(g - centre));
  let facet = normalize(normal + (vec3f(luck.x, luck.z, luck.y) - 0.5) * 1.6);
  let mirror = pow(max(dot(facet, halfway), 0.0), 40.0);
  return grain * mirror * step(0.3, luck.z);
}

// Sugary grain: each little cell of the salt at `local` a little brighter or
// darker than the next, the cells about a screen pixel or two across
// wherever the salt is, so it reads as granular near or far: 1 on average.
fn sugar(local: vec3f, n: vec3f, pixel: f32) -> f32 {
  let a = abs(n);
  var q = local.xy;
  if (a.x >= a.y && a.x >= a.z) {
    q = local.zy;
  } else if (a.y >= a.z) {
    q = local.xz;
  }
  let fine = floor(q / max(0.008, pixel * 1.5));
  let coarse = floor(q / max(0.03, pixel * 4.0));
  return 0.9 + 0.12 * scatter(fine, 41.0) + 0.08 * scatter(coarse, 43.0);
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let n = normalize(input.local_normal);
  // Each axis's share, sharpened so the projections meet in narrow seams.
  var weights = pow(abs(n), vec3f(4.0));
  weights /= weights.x + weights.y + weights.z;
  let surface = normalize(input.normal);
  // Each projection's coordinates. v runs down the image, so the second axis
  // is negated to put the image's up along it.
  let p = input.local / tile;
  let uv_x = vec2f(p.z, -p.y);
  let uv_y = vec2f(p.x, -p.z);
  let uv_z = vec2f(p.x, -p.y);

  // The way to the eye, in the model's own frame.
  let model_scale = scale_of(draw.model);
  let model_rotation = mat3x3f(draw.model[0].xyz / model_scale.x, draw.model[1].xyz / model_scale.y, draw.model[2].xyz / model_scale.z);
  let view_rotation = mat3x3f(scene.view[0].xyz, scene.view[1].xyz, scene.view[2].xyz);
  let eye_at = -(transpose(view_rotation) * scene.view[3].xyz);
  let v = transpose(model_rotation) * normalize(eye_at - input.world);

  var crystal = vec4f(1.0, 1.0, 1.0, 0.5);
  var inner = vec3f(1.0);
  var shade = 1.0;
  if (draw.settings.w > 0.5) {
    // Each projection looks `clear_depth` deeper in along the view.
    let depth = clear_depth / tile;
    inner = textureSample(crystals, surface_sampler, uv_x - vec2f(v.z, -v.y) / max(abs(v.x), 0.3) * depth).rgb * weights.x +
      textureSample(crystals, surface_sampler, uv_y - vec2f(v.x, -v.z) / max(abs(v.y), 0.3) * depth).rgb * weights.y +
      textureSample(crystals, surface_sampler, uv_z - vec2f(v.x, -v.y) / max(abs(v.z), 0.3) * depth).rgb * weights.z;
    crystal = textureSample(crystals, surface_sampler, uv_x) * weights.x +
      textureSample(crystals, surface_sampler, uv_y) * weights.y +
      textureSample(crystals, surface_sampler, uv_z) * weights.z;
    // The same texture, far coarser and blurred, varies it over a few repeats.
    let broad = textureSampleLevel(crystals, surface_sampler, uv_x * 0.23 + 0.31, 6.0).g * weights.x +
      textureSampleLevel(crystals, surface_sampler, uv_y * 0.23 + 0.57, 6.0).g * weights.y +
      textureSampleLevel(crystals, surface_sampler, uv_z * 0.23 + 0.13, 6.0).g * weights.z;
    shade = 1.0 + (broad - 0.85) * variation * 4.0;
  }

  // Whiteout blend: each projection's relief tilts the surface's own normal,
  // swizzled into that projection's axes and back.
  var local = n;
  if (draw.settings.z > 0.5) {
    var tx = bump(uv_x);
    var ty = bump(uv_y);
    var tz = bump(uv_z);
    tx = vec3f(tx.xy + n.zy, abs(tx.z) * n.x);
    ty = vec3f(ty.xy + n.xz, abs(ty.z) * n.y);
    tz = vec3f(tz.xy + n.xy, abs(tz.z) * n.z);
    local = normalize(tx.zyx * weights.x + ty.xzy * weights.y + tz.xyz * weights.z);
  }
  // Back to the world: the model's rotation, without its scale.
  let scale = scale_of(draw.model);
  let rotation = mat3x3f(draw.model[0].xyz / scale.x, draw.model[1].xyz / scale.y, draw.model[2].xyz / scale.z);
  let pixel = length(fwidth(input.world));
  let struck = damage(input.rest, surface, pixel);
  let normal = normalize(rotation * local - struck.slope);

  let swatch = textureSample(palette, surface_sampler, input.uv).rgb;
  let kind = kind_of(input.uv);
  let salty = kind == salt_kind;
  // Salt is white: the palette and the crystals give it light and shade, and
  // only a breath of their color; the rest keep their swatch's own color,
  // stone with a little of the grain.
  let luma = vec3f(0.299, 0.587, 0.114);
  let grain = mix(1.0, dot(crystal.rgb, luma), 0.6);
  let painted = mix(vec3f(dot(swatch, luma)), swatch, 0.25);
  // The crust: coarse white granules in clumps (where the texture is busy
  // and dull), gathered in patches a unit or so across and piled on the faces
  // turned up; between them the salt is smooth, milky and a little warm.
  let tone = dot(crystal.rgb, luma);
  let clumps = 1.0 - smoothstep(0.3, 0.7, crystal.a);
  let crusted = smoothstep(0.25, 0.8, clumps * 0.8 + smoothstep(0.3, 0.85, surface.y) * 0.45) * select(0.0, 1.0, salty) *
    (1.0 - struck.broken);
  let crystal_tone = mix(vec3f(0.86, 0.83, 0.78), vec3f(1.0), smoothstep(0.68, 0.98, tone + crusted * 0.08));
  var base = mix(vec3f(1.0), painted, palette_strength) * crystal_tone * shade * vec3f(1.0, 0.97, 0.93);
  if (kind == crystal_kind) {
    base = mix(swatch, vec3f(1.0, 0.98, 0.96), 0.8);
  } else if (kind == pebble_kind) {
    base = swatch * grain * 1.1;
  } else if (kind == plant_kind || kind == plain_kind) {
    base = swatch;
  }
  // A scar breaks through the crust to the clean, glassy salt inside, a
  // touch cooler; its lip and ridges are white powder, and it darkens
  // toward its floor.
  let fresh = vec3f(0.9, 0.91, 0.93) * (0.94 + 0.06 * tone);
  let opened = mix(draw.color.rgb * base, fresh, struck.broken * select(0.0, 0.8, salty));
  let albedo = mix(opened, vec3f(1.0, 0.99, 0.97), struck.crushed * 0.7) * (1.0 - 0.45 * struck.hollow);
  if (draw.settings.x < 0.5) {
    return vec4f(albedo, draw.color.a);
  }
  // Only salt and stone take the crystals' relief.
  let shaded = select(normalize(rotation * n - struck.slope), normal, salty || kind == pebble_kind);
  let to_light = normalize(-scene.light_direction.xyz);
  let sun = sunlit(input.world, surface);
  let to_eye = normalize(scene.eye.xyz - input.world);
  let halfway = normalize(to_light + to_eye);
  let facing = dot(shaded, to_light);
  // Light from all round comes more from the sky than the ground; a dent's
  // floor gets less of it.
  let ambient = hemisphere(shaded) * (1.0 - 0.35 * struck.hollow);

  if (kind == plant_kind || kind == plain_kind) {
    let finish = finish_of(swatch_of(input.uv));
    let wrapped = max((facing + 0.3) / 1.3, 0.0);
    let diffuse = albedo * (1.0 - finish.y) * (ambient + scene.light_color.xyz * wrapped * sun);
    return vec4f(diffuse + mirrored(albedo, shaded, to_light, to_eye, finish.x, finish.y, sun) + albedo * finish.z, draw.color.a);
  }
  if (kind == pebble_kind) {
    let lit = albedo * (ambient + scene.light_color.xyz * max(facing, 0.0) * sun);
    return vec4f(lit + mirrored(albedo, shaded, to_light, to_eye, 0.45, 0.0, sun), draw.color.a);
  }
  if (kind == crystal_kind) {
    // Clear crystal: a sharp highlight, a bright rim where it turns away,
    // and light caught inside it, which shows most against the sun.
    let rim = pow(1.0 - max(dot(shaded, to_eye), 0.0), 3.0);
    let flash = pow(max(dot(shaded, halfway), 0.0), 320.0) * 2.5 * sun;
    let inside = 0.35 + 0.45 * pow(max(dot(to_eye, -to_light), 0.0), 2.0);
    let wrapped = max((facing + 0.5) / 1.5, 0.0);
    let lit = albedo * (ambient * 1.2 + scene.light_color.xyz * wrapped * mix(sun, 1.0, 0.5) * 0.7) +
      vec3f(1.0, 0.97, 0.94) * scene.light_color.xyz * inside * 0.45 + vec3f(0.93, 0.92, 1.0) * rim * 0.55 +
      scene.light_color.xyz * flash;
    return vec4f(lit, draw.color.a);
  }

  // Salt passes light: it wraps far past the shadow line and scatters well
  // into the salt's own shade, which stays bright and a little cool; it
  // glows warm where the sun is behind it, and its edges glow as light comes
  // through them.
  let wrapped = max((facing + 0.5) / 1.5, 0.0);
  let scattered = mix(sun, 1.0, 0.45);
  // Light inside the salt evens it out: every face keeps some of the light
  // whichever way it faces, so its hewn faces show in soft but clear steps.
  // In a dent the light falls harder, so its chips' facets show.
  let held = mix(0.3 + 0.7 * wrapped, 0.15 + 0.85 * max(facing, 0.0), struck.broken * 0.55);
  let behind = pow(max(dot(to_eye, -to_light), 0.0), 3.0) * (1.0 - max(facing, 0.0)) * 0.35;
  let edge = pow(1.0 - max(dot(shaded, to_eye), 0.0), 2.5) * 0.45;
  // Gloss narrows and strengthens the highlight: polished crystal faces
  // glint, past white, and mirror the sky at a slant; the granular fill
  // between them barely shines.
  let gloss = mix(mix(0.75, 0.05, crusted), 0.95, struck.broken) * (1.0 - struck.crushed);
  let roughness = mix(0.6, 0.2, gloss);
  let salt_f0 = vec3f(0.045);
  let glint = highlight(shaded, to_light, to_eye, roughness) * fresnel(salt_f0, dot(halfway, to_eye), 0.0) *
    scene.light_color.xyz * mix(sun, 1.0, 0.3) * mix(0.35, 1.0, gloss);
  let mirror = sky_seen(reflect(-to_eye, shaded), roughness) * fresnel(salt_f0, dot(shaded, to_eye), roughness) * gloss * 0.4;
  let shine = glint + mirror;
  let glinting = glints(input.local, n, shaded, halfway, pixel) * (1.0 + 3.0 * crusted) * (1.0 - struck.crushed);
  // The crust is whiter than the salt it sits on, and sugary.
  let sugared = mix(albedo, vec3f(1.0, 0.995, 0.98), crusted * 0.45) * mix(1.0, sugar(input.local, n, pixel), 0.5 + 0.5 * crusted);
  // The salt's shade is warm, the light glowing through it.
  let glow = mix(vec3f(1.0, 0.94, 0.87), vec3f(1.0), wrapped);
  let lit = sugared * (ambient * 1.6 * glow + scene.light_color.xyz * held * scattered) +
    vec3f(1.0, 0.9, 0.75) * scene.light_color.xyz * behind * albedo +
    (scene.ambient.xyz + scene.light_color.xyz * 0.5) * edge * albedo +
    shine + scene.light_color.xyz * glinting * mix(sun, 1.0, 0.3);

  // Clear salt: in places, a block or two across, the rock is halite you can
  // see into. Its surface is glassy, a sharp highlight and the sky caught at
  // its rim, and under it the salt deeper in shows, shifting as the view
  // does, its cracks bright, lit by the light coming through, the more with
  // the sun behind it.
  let clear = smoothstep(0.56, 0.74, noise3(input.local * 0.55 + vec3f(3.1, 0.0, 1.7))) *
    (1.0 - struck.crushed) * select(0.0, 1.0, kind == salt_kind) * draw.parameters.clear;
  let deep = dot(inner, luma);
  let cracks = smoothstep(0.9, 1.0, deep);
  // Clear salt glows: lighter than the opaque, milky, the light inside it
  // brightest where it comes through, its cracks bright.
  let inside = vec3f(0.98, 0.95, 0.91) * (0.6 + 0.4 * deep) * mix(vec3f(1.0), painted, 0.4);
  let into_sun = pow(max(dot(to_eye, -to_light), 0.0), 3.0);
  let through = scene.light_color.xyz * (0.35 + 0.45 * wrapped + 1.2 * into_sun) * mix(sun, 1.0, 0.65);
  let rim = pow(1.0 - max(dot(shaded, to_eye), 0.0), 4.0);
  let sharp = pow(max(dot(shaded, halfway), 0.0), 260.0) * 2.4 * sun;
  let seen_into = inside * (ambient * 1.6 + through * 0.85) +
    vec3f(1.0, 0.97, 0.9) * cracks * through * 0.45 +
    (scene.ambient.xyz * 1.8 + vec3f(0.1)) * rim * 0.6 +
    scene.light_color.xyz * sharp;
  return vec4f(mix(lit, seen_into, clear * 0.8), draw.color.a);
}

