// Loose salt lies over the floor like fresh snow, `depth` deep. Gnorps plough
// through it: where they have trodden it packs down toward `packed`, and the
// salt they push aside heaps up in low banks beside the deeper grooves. The
// earth patches and the rock's meadow clear it away to `bare`.
//
// A continuous height field: the trodden field's `cells` x `cells` samples,
// `spacing` apart from `origin`, are the host's field for this material
// (render.Field, binding 3), which src/trails.blot keeps up to date, and a
// cubic B-spline through them lays the surface. The arena is drawn in
// `tiles` x `tiles` tiles `tile_size` across that carry nothing of their own,
// so they share one instanced draw. src/trails.blot works out the same
// surface for what lies on it.
const cells = 193u;
const spacing = 0.5;
const origin = -48.0;
const tile_size = 8.0;
const tiles = 12u;
// The height, and everything src/trails.blot repeats of it: the powder's
// `depth`, drifting `drift` up and down every so often (`drift_scale` per
// unit); salt packs from `pack_start` of the trodden field down to `packed`
// at `pack_end`; the bank it was pushed into, up to `bank` high, peaks at
// `heap_peak` and is gone by `heap_end`; cleared, at 2, the floor lies at
// `bare`.
const depth = 0.3;
const drift = 0.06;
const drift_scale = 0.38;
const packed = 0.03;
const pack_start = 0.12;
const pack_end = 0.62;
const bank = 0.14;
const heap_peak = 0.16;
const heap_end = 0.42;
const bare = -0.015;
const hash_scale = 0.1031;
const hash_offset = 33.33;
struct Scene {
  view: mat4x4f, projection: mat4x4f, ambient: vec4f,
  light_direction: vec4f, light_color: vec4f, light_view_projection: mat4x4f,
  shadow: vec4f, zenith: vec4f, horizon: vec4f, ground: vec4f, eye: vec4f,
};
struct Parameters { unused0: f32, unused1: f32, unused2: f32, unused3: f32 };
struct Draw { model: mat4x4f, normal: mat4x4f, color: vec4f, settings: vec4f, parameters: Parameters };
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;
