fn packing(w: f32) -> f32 { return smoothstep(pack_start, pack_end, w); }
// The bank beside a groove, on its outer edge, where the field has barely
// begun.
fn heaping(w: f32) -> f32 {
  return smoothstep(0.0, heap_peak, w) * (1.0 - smoothstep(heap_peak, heap_end, w));
