  // walls and floor a plough has cut, most where the cut is steep.
  let wall = smoothstep(0.05, 0.4, 1.0 - n.y);
  let deep = clamp(packed_down * (0.5 + wall * 0.5) + v.trodden.y * 0.2, 0.0, 1.0) * (1.0 - cleared);
  albedo = mix(albedo, vec3f(0.5, 0.7, 0.98), deep * 0.5);
