    let clip = scene.light_view_projection * vec4f(v.world + n * scene.shadow.z, 1.0);
    let ndc = clip.xyz / clip.w;
    let at = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
    if (all(at >= vec2f(0.0)) && all(at <= vec2f(1.0)) && ndc.z < 1.0) {
