  // walls hide its floor from much of the sky.
  let lit = max(dot(n, to_light), 0.0) * shadow;
  let sky = scene.ambient.rgb * vec3f(0.78, 0.9, 1.25) * (1.0 - 0.4 * packed_down);
  var color = albedo * (sky + scene.light_color.rgb * lit);
