  let point = 1.0 - smoothstep(0.06, 0.14, length(grid - cell - spot));
  let facet = normalize(n + vec3f(hash(cell + vec2f(7.1, 3.3)) - 0.5, 0.0, hash(cell + vec2f(1.7, 9.2)) - 0.5) * 1.6);
