// A black card with a thick rounded white border; its portrait is a 3D inset.
struct Parameters { part: f32, state: f32, scale: f32, count: f32 };
const card = 0u;
struct Screen { size: vec4f };
struct Sprite { rect: vec4f, uv: vec4f, color: vec4f, parameters: vec4f };
