@group(0) @binding(1) var<storage,read> sprites: array<Sprite>;
struct Corner {
  @builtin(position) position: vec4f,
  @location(0) local: vec2f,
  @location(1) @interpolate(flat) size: vec2f,
  @location(2) @interpolate(flat) parameters: vec4f,
};
@vertex fn vertex(@builtin(vertex_index) v:u32,@builtin(instance_index) i:u32)->Corner {
  let sprite=sprites[i];
  let corner=array<vec2f,6>(vec2f(0,0),vec2f(1,0),vec2f(0,1),vec2f(0,1),vec2f(1,0),vec2f(1,1))[v];
  let at=sprite.rect.xy+corner*sprite.rect.zw;
  return Corner(vec4f(at.x/screen.size.x*2.0-1.0,1.0-at.y/screen.size.y*2.0,0,1),corner*sprite.rect.zw,sprite.rect.zw,sprite.parameters);
}
fn box(p:vec2f,c:vec2f,h:vec2f,r:f32)->f32 {
  let q=abs(p-c)-h+r;
  return length(max(q,vec2f(0)))+min(max(q.x,q.y),0.0)-r;
}
@fragment fn fragment(c:Corner)->@location(0) vec4f {
  let s=max(c.parameters.z,.001);
  let p=c.local/s;
  let size=c.size/s;
  let d=box(p,size*.5,size*.5-vec2f(1),18.0);
  let aa=.65/s;
  let alpha=1.0-smoothstep(-aa,aa,d);
  let border=smoothstep(-5.0-aa,-5.0+aa,d);
  return vec4f(vec3f(border),alpha);
}

