// Text: the material's texture is a font's distance field (models/font), whose
// 0.5 is a glyph's edge, smoothed over a screen pixel at any size. The
// sprite's color is the ink's.
//
// What a sprite passes: how far the text has crumbled away, 0 to 1 (see
// bubble.wgsl), the screen's scale (pixels per pixel at 720 lines) and the
// crumbling's origin in pixels. Text over a bubble passes the bubble's, so its
// words crumble with it (src/speech.blot).
struct Parameters {
  crumbled: f32,
  scale: f32,
  origin_x: f32,
  origin_y: f32,
};
struct Screen {
  size: vec4f,
};
struct Sprite {
  rect: vec4f,
  uv: vec4f,
  color: vec4f,
  parameters: vec4f,
};
@group(0) @binding(0) var<uniform> screen: Screen;
@group(0) @binding(1) var<storage, read> sprites: array<Sprite>;
@group(0) @binding(2) var image: texture_2d<f32>;
@group(0) @binding(3) var image_sampler: sampler;

struct Corner {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
  @location(1) color: vec4f,
  @location(2) @interpolate(flat) parameters: vec4f,
};

@vertex fn vertex(@builtin(vertex_index) vertex: u32, @builtin(instance_index) index: u32) -> Corner {
  let sprite = sprites[index];
  let corner = array<vec2f, 6>(vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(0.0, 1.0), vec2f(0.0, 1.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0))[vertex];
  let pixel = sprite.rect.xy + corner * sprite.rect.zw;
  var output: Corner;
  output.position = vec4f(pixel.x / screen.size.x * 2.0 - 1.0, 1.0 - pixel.y / screen.size.y * 2.0, 0.0, 1.0);
  output.uv = mix(sprite.uv.xy, sprite.uv.zw, corner);
  output.color = sprite.color;
  output.parameters = sprite.parameters;
  return output;
}

// The crumbling's noise, the same as bubble.wgsl's.
fn hash(p: vec2f) -> f32 {
  var q = fract(vec3f(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}
fn smooth_noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2f(1.0, 0.0)), u.x),
    mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), u.x), u.y);
}
fn crumble_noise(pixel: vec2f, origin: vec2f, scale: f32) -> f32 {
  let p = (pixel - origin) / (max(scale, 0.001) * 14.0);
  return smooth_noise(p) * 0.5 + smooth_noise(p * 2.7 + 17.1) * 0.3 + hash(floor((pixel - origin) / max(scale * 1.5, 0.5))) * 0.2;
}

// The sprite's parameters by name.
fn named(v: vec4f) -> Parameters {
  return Parameters(v.x, v.y, v.z, v.w);
}

@fragment fn fragment(corner: Corner) -> @location(0) vec4f {
  let p = named(corner.parameters);
  let distance = textureSampleLevel(image, image_sampler, corner.uv, 0.0).r;
  let edge = max(fwidth(distance) * 0.7, 0.001);
  let ink = smoothstep(0.5 - edge, 0.5 + edge, distance);
  let crumbled = p.crumbled;
  let left = crumble_noise(corner.position.xy, vec2f(p.origin_x, p.origin_y), p.scale) - (crumbled * 1.25 - 0.1);
  if (crumbled <= 0.0) {
    return vec4f(corner.color.rgb, corner.color.a * ink);
  }
  // Letters go with the slab, greyed with dust at its breaking edge.
  let dusty = mix(corner.color.rgb, vec3f(0.52, 0.51, 0.49), smoothstep(0.07, 0.0, left) * 0.8);
  return vec4f(dusty, corner.color.a * ink * step(0.0, left));
}

