// The universe the pause menu looks out on (src/menu.blot): a sprite over
// the whole screen, seen through the camera, so the sky turns as the view
// does. Deep space, inky blue going black; the Milky Way across it, dusty and
// split by dark lanes; glowing clouds of pink, violet and teal; stars in
// three layers of size and brightness, each its own color and twinkling, the
// brightest with a soft halo; and now and then a shooting star. While the
// camera flies the stars streak, their trails reaching back toward the middle
// of the view, the longer the faster it goes.
//
// Its uv is the camera's rotation, a quaternion (x, y, z, w).
//
// What the sprite passes (src/menu.blot): the seconds; how far it has faded
// in, 0 to 1; how fast the view flies, 0 still to 1 fastest; and the camera's
// focal length.
struct Parameters {
  seconds: f32,
  fade: f32,
  warp: f32,
  focal: f32,
};
struct Screen {
  size: vec4f,
};
struct Sprite {
  rect: vec4f,
  uv: vec4f,
  color: vec4f,
  parameters: vec4f,
};
@group(0) @binding(0) var<uniform> screen: Screen;
@group(0) @binding(1) var<storage, read> sprites: array<Sprite>;
@group(0) @binding(2) var image: texture_2d<f32>;
@group(0) @binding(3) var image_sampler: sampler;

struct Corner {
  @builtin(position) position: vec4f,
  // Pixels from the sprite's top left.
  @location(0) local: vec2f,
  @location(1) @interpolate(flat) size: vec2f,
  @location(2) @interpolate(flat) rotation: vec4f,
  @location(3) @interpolate(flat) color: vec4f,
  @location(4) @interpolate(flat) parameters: vec4f,
};

@vertex fn vertex(@builtin(vertex_index) vertex: u32, @builtin(instance_index) index: u32) -> Corner {
  let sprite = sprites[index];
  let corner = array<vec2f, 6>(vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(0.0, 1.0), vec2f(0.0, 1.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0))[vertex];
  let pixel = sprite.rect.xy + corner * sprite.rect.zw;
  var output: Corner;
  output.position = vec4f(pixel.x / screen.size.x * 2.0 - 1.0, 1.0 - pixel.y / screen.size.y * 2.0, 0.0, 1.0);
  output.local = corner * sprite.rect.zw;
  output.size = sprite.rect.zw;
  output.rotation = sprite.uv;
  output.color = sprite.color;
  output.parameters = sprite.parameters;
  return output;
}

fn rotate(q: vec4f, v: vec3f) -> vec3f {
  return v + 2.0 * cross(q.xyz, cross(q.xyz, v) + q.w * v);
}

// Four random values in 0..1 for the whole-numbered `cell`.
fn hash(cell: vec3f, seed: u32) -> vec4f {
  let c = vec3u(vec3i(cell));
  var h = (c.x * 0x8da6b343u) ^ (c.y * 0xd8163841u) ^ (c.z * 0xcb1ab31fu) ^ (seed * 0x9e3779b9u);
  var found = vec4f(0.0);
  for (var lane = 0; lane < 4; lane++) {
    h ^= h >> 16u;
    h *= 0x7feb352du;
    h ^= h >> 15u;
    h *= 0x846ca68bu;
    h ^= h >> 16u;
    found[lane] = f32(h >> 8u) / 16777216.0;
    h += 0x632be5abu;
  }
  return found;
}

// Smooth noise over space, 0..1, and octaves of it.
fn noise(p: vec3f, seed: u32) -> f32 {
  let i = floor(p);
  let f = p - i;
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(hash(i, seed).x, hash(i + vec3f(1.0, 0.0, 0.0), seed).x, u.x);
  let b = mix(hash(i + vec3f(0.0, 1.0, 0.0), seed).x, hash(i + vec3f(1.0, 1.0, 0.0), seed).x, u.x);
  let c = mix(hash(i + vec3f(0.0, 0.0, 1.0), seed).x, hash(i + vec3f(1.0, 0.0, 1.0), seed).x, u.x);
  let d = mix(hash(i + vec3f(0.0, 1.0, 1.0), seed).x, hash(i + vec3f(1.0, 1.0, 1.0), seed).x, u.x);
  return mix(mix(a, b, u.y), mix(c, d, u.y), u.z);
}
fn fbm(p: vec3f, seed: u32) -> f32 {
  var sum = 0.0;
  var weight = 0.5;
  var q = p;
  for (var octave = 0u; octave < 4u; octave++) {
    sum += weight * noise(q, seed + octave * 7u);
    q = q * 2.03 + vec3f(1.7, -2.3, 0.9);
    weight *= 0.5;
  }
  return sum / 0.9375;
}

// The Milky Way's plane, and the sky away from the stars: deep space, the
// galaxy's band and the clouds of gas glowing in it.
const galaxy = vec3f(0.33, 0.62, 0.71);
fn space(direction: vec3f) -> vec3f {
  var color = mix(vec3f(0.006, 0.008, 0.025), vec3f(0.018, 0.025, 0.07), smoothstep(-0.6, 0.6, direction.y));
  let across = dot(direction, galaxy);
  let band = exp(-across * across / 0.05);
  let dust = fbm(direction * 3.5, 3u);
  let lanes = smoothstep(0.48, 0.66, fbm(direction * 7.0 + vec3f(3.0), 5u));
  let milky = band * (0.35 + 0.65 * dust) * (1.0 - 0.75 * lanes * smoothstep(0.2, 0.8, band));
  color += vec3f(0.42, 0.4, 0.58) * milky * 0.38;
  color += vec3f(0.9, 0.75, 0.55) * pow(band, 6.0) * dust * 0.12;
  let pink = smoothstep(0.52, 0.8, fbm(direction * 2.2 + vec3f(7.0, 1.0, -3.0), 11u));
  let teal = smoothstep(0.55, 0.82, fbm(direction * 2.8 - vec3f(5.0, 2.0, 4.0), 13u));
  let violet = smoothstep(0.5, 0.75, fbm(direction * 1.6 + vec3f(-2.0, 6.0, 1.0), 17u));
  color += vec3f(0.55, 0.12, 0.38) * pink * (0.25 + 0.5 * band);
  color += vec3f(0.04, 0.3, 0.38) * teal * (0.2 + 0.4 * band);
  color += vec3f(0.22, 0.1, 0.45) * violet * 0.22;
  return color;
}

// One layer of stars, `scale` cells across a unit of direction, a star in a
// share `density` of them: how bright the star near `direction` shines, in
// color, with `pixel` radians a pixel. Each lies well inside its cell, so
// only `direction`'s cell needs looking at.
fn stars(direction: vec3f, scale: f32, density: f32, size: f32, seconds: f32, pixel: f32, seed: u32) -> vec3f {
  let p = direction * scale;
  let cell = floor(p);
  let h = hash(cell, seed);
  if (h.w > density) {
    return vec3f(0.0);
  }
  let star = normalize(cell + 0.25 + 0.5 * h.xyz);
  let apart = length(direction - star) / pixel;
  let magnitude = h.w / density;
  let radius = size * (0.6 + 0.9 * (1.0 - magnitude));
  let core = exp(-apart * apart / (radius * radius));
  let halo = exp(-apart / (radius * 4.0)) * 0.12 * (1.0 - magnitude);
  let warm = vec3f(1.0, 0.78, 0.58);
  let cool = vec3f(0.66, 0.8, 1.0);
  let tint = mix(mix(warm, vec3f(1.0), smoothstep(0.2, 0.5, h.x)), cool, smoothstep(0.55, 0.9, h.x));
  let twinkle = 0.7 + 0.3 * sin(seconds * (1.5 + 3.0 * h.y) + h.z * 40.0);
  return tint * (core + halo) * twinkle * (1.4 - magnitude);
}

fn starfield(direction: vec3f, seconds: f32, pixel: f32, faint: bool) -> vec3f {
  var light = stars(direction, 28.0, 0.22, 1.4, seconds, pixel, 21u);
  light += stars(direction, 70.0, 0.3, 1.0, seconds, pixel, 23u) * 0.75;
  if (faint) {
    light += stars(direction, 160.0, 0.4, 0.8, seconds, pixel, 29u) * 0.45;
  }
  return light;
}

// A shooting star every few seconds, somewhere across the screen: where it
// shows at the pixel `at` (in screen heights from the middle).
fn shooting(at: vec2f, seconds: f32) -> f32 {
  let every = 4.5;
  let which = floor(seconds / every);
  let h = hash(vec3f(which, 3.0, 7.0), 31u);
  let t = (seconds - which * every) / 0.7;
  if (t > 1.0 || h.w < 0.3) {
    return 0.0;
  }
  let start = vec2f(h.x - 0.5, h.y * 0.5 - 0.4) * vec2f(1.6, 1.0);
  let way = normalize(vec2f(select(-1.0, 1.0, h.z > 0.5), 0.45 + 0.3 * h.z));
  let head = start + way * t * 0.9;
  let back = at - head;
  let along = dot(back, -way);
  let off = length(back + way * along);
  let tail = clamp(along / 0.25, 0.0, 1.0);
  let streak = (1.0 - smoothstep(0.0, 0.003, off)) * step(0.0, along) * (1.0 - tail);
  return streak * sin(t * 3.1415927) * 1.6;
}

// The sprite's parameters by name.
fn named(v: vec4f) -> Parameters {
  return Parameters(v.x, v.y, v.z, v.w);
}

@fragment fn fragment(corner: Corner) -> @location(0) vec4f {
  let p = named(corner.parameters);
  let seconds = p.seconds;
  let fade = p.fade;
  let warp = p.warp;
  let focal = p.focal;
  let q = corner.rotation;
  // The direction through this pixel, in the world.
  let aspect = corner.size.x / corner.size.y;
  let ndc = vec2f(corner.local.x / corner.size.x * 2.0 - 1.0, 1.0 - corner.local.y / corner.size.y * 2.0);
  let direction = normalize(rotate(q, vec3f(ndc.x * aspect / focal, ndc.y / focal, -1.0)));
  let forward = rotate(q, vec3f(0.0, 0.0, -1.0));
  let pixel = 2.0 / (focal * corner.size.y);
  var color = space(direction);
  if (warp < 0.02) {
    color += starfield(direction, seconds, pixel, true);
  } else {
    // Flying, each star smears back toward the middle of the view.
    var trail = vec3f(0.0);
    for (var sample = 0; sample < 7; sample++) {
      let back = f32(sample) / 6.0;
      let toward = normalize(direction + (direction - forward) * back * warp * 0.6);
      trail = max(trail, starfield(toward, seconds, pixel, false) * (1.0 - 0.75 * back));
    }
    color += trail * (1.0 + warp);
    // And light gathers at the middle of the view, ahead.
    let ahead = max(dot(direction, forward), 0.0);
    color += vec3f(0.35, 0.45, 0.8) * pow(ahead, 30.0) * warp * 0.6;
  }
  let at = vec2f(ndc.x * aspect, ndc.y) * 0.5;
  color += vec3f(0.9, 0.95, 1.0) * shooting(at, seconds) * (1.0 - warp);
  // Darker toward the corners.
  color *= 1.0 - 0.35 * smoothstep(0.5, 1.4, length(ndc * vec2f(aspect * 0.6, 1.0)));
  return vec4f(color, fade * corner.color.a);
}

