// One walking or ragdoll pose: 32 yaw views by 17 elevations.
// Runtime cells are 80x112; normalized capture geometry matches the source.
// The model origin is the capture center; local +Z is forward and +Y is up.
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  settings: vec4f,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(1) @binding(0) var<uniform> draw: Draw;
@group(1) @binding(1) var atlas: texture_2d<f32>;
@group(1) @binding(2) var atlas_sampler: sampler;
@group(1) @binding(3) var normal_atlas: texture_2d<f32>;
@group(1) @binding(4) var outline_atlas: texture_2d<f32>;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
  @location(1) @interpolate(flat) frame: vec2f,
  @location(2) @interpolate(flat) direction: vec3f,
  @location(3) @interpolate(flat) object_right: vec3f,
  @location(4) @interpolate(flat) object_up: vec3f,
  @location(5) @interpolate(flat) object_front: vec3f,
};

struct InstanceInput {
  @location(3) model0: vec4f,
  @location(4) model1: vec4f,
  @location(5) model2: vec4f,
  @location(6) model3: vec4f,
};

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  return billboard(input, draw.model);
}

@vertex fn vertex_instanced(input: VertexInput, instance: InstanceInput) -> VertexOutput {
  return billboard(input, mat4x4f(instance.model0, instance.model1, instance.model2, instance.model3));
}

fn billboard(input: VertexInput, model: mat4x4f) -> VertexOutput {
  // Inverse of the rigid camera view. The translation is expressed in the
  // view's right/up/back basis, which is stored across its first three columns.
  let view_translation = scene.view[3].xyz;
  let camera = -vec3f(
    dot(scene.view[0].xyz, view_translation),
    dot(scene.view[1].xyz, view_translation),
    dot(scene.view[2].xyz, view_translation),
  );
  let center = model[3].xyz;
  let object_right = normalize(model[0].xyz);
  let object_up = normalize(model[1].xyz);
  let object_front = normalize(model[2].xyz);
  let offset = camera - center;
  var toward_camera = object_front;
  if (dot(offset, offset) > 0.000000000001) {
    toward_camera = normalize(offset);
  }
  let local_direction = vec3f(
    dot(toward_camera, object_right),
    dot(toward_camera, object_up),
    dot(toward_camera, object_front),
  );

  // Column zero is front (+Z); increasing columns circle toward local +X.
  // Keep fractional coordinates so the captures blend instead of jumping at
  // every half-frame boundary. The last column blends back into column zero.
  var yaw = 0.0;
  if (dot(local_direction.xz, local_direction.xz) > 0.000000000001) {
    yaw = atan2(local_direction.x, local_direction.z);
  }
  let column = fract(yaw / (2.0 * 3.14159265359)) * 32.0;
  // Row zero is viewed from above and row sixteen from below.
  let elevation = atan2(local_direction.y, length(local_direction.xz));
  let row = clamp((0.5 * 3.14159265359 - elevation) *
    (16.0 / 3.14159265359), 0.0, 16.0);

  // Use the same yaw for the billboard and atlas, including at the poles.
  // A separate pole fallback would roll the quad without rotating its image.
  let right = object_right * cos(yaw) - object_front * sin(yaw);
  let up = normalize(cross(toward_camera, right));
  let world_position = center + right * input.position.x * length(model[0].xyz) +
    up * input.position.y * length(model[1].xyz);

  var output: VertexOutput;
  output.position = scene.projection * scene.view * vec4f(world_position, 1.0);
  output.uv = input.uv;
  output.frame = vec2f(column, row);
  output.direction = local_direction;
  output.object_right = object_right;
  output.object_up = object_up;
  output.object_front = object_front;
  return output;
}

// Register the captures against the robot's box-shaped body. The source
// silhouettes put it at x=-34..34, y=-21..69 and z=-22..22 capture pixels;
// one local unit is 224 pixels. This is only a sampling proxy, not geometry.
// A ray missing the body keeps the capture-center plane for arms and legs.
fn body_point(point: vec3f, direction: vec3f) -> vec3f {
  let low = vec3f(-34.0, -21.0, -22.0) / 224.0;
  let high = vec3f(34.0, 69.0, 22.0) / 224.0;
  var near = -1000000.0;
  var far = 1000000.0;
  for (var axis = 0u; axis < 3u; axis += 1u) {
    if (abs(direction[axis]) < 0.000001) {
      if (point[axis] < low[axis] || point[axis] > high[axis]) {
        return point;
      }
    } else {
      let a = (low[axis] - point[axis]) / direction[axis];
      let b = (high[axis] - point[axis]) / direction[axis];
      near = max(near, min(a, b));
      far = min(far, max(a, b));
    }
  }
  if (far < near) {
    return point;
  }
  return point + direction * far;
}

// The walking sheets contain real alpha. Premultiply before mixing captures
// so transparent texels never tint the sprite, including its dark details.
fn premultiplied(color: vec4f) -> vec4f {
  return vec4f(color.rgb * color.a, color.a);
}

fn capture_uv(frame: vec2u, point: vec3f) -> vec2f {
  let yaw = f32(frame.x) * (2.0 * 3.14159265359 / 32.0);
  let elevation = 0.5 * 3.14159265359 - f32(frame.y) * (3.14159265359 / 16.0);
  let right = vec3f(cos(yaw), 0.0, -sin(yaw));
  let up = vec3f(-sin(yaw) * sin(elevation), cos(elevation), -cos(yaw) * sin(elevation));
  let uv = vec2f(0.5 + dot(point, right) / (5.0 / 7.0), 0.5 - dot(point, up));
  return uv;
}

fn filtered(layer: texture_2d<f32>, frame: vec2u, uv: vec2f) -> vec4f {
  let dimensions = vec2f(textureDimensions(layer));
  let cell = dimensions / vec2f(32.0, 17.0);
  // Filter premultiplied texels, not the colored RGB under zero alpha in the
  // source sheets. Clamp both taps to this capture so frames cannot bleed.
  let pixel = clamp(uv * cell, vec2f(0.5), cell - vec2f(0.5));
  let at = vec2f(frame) * cell + pixel - vec2f(0.5);
  let low = vec2i(floor(at));
  let high = min(low + vec2i(1), vec2i((vec2f(frame) + vec2f(1.0)) * cell) - vec2i(1));
  let weight = fract(at);
  let upper = mix(premultiplied(textureLoad(layer, low, 0)),
    premultiplied(textureLoad(layer, vec2i(high.x, low.y), 0)), weight.x);
  let lower = mix(premultiplied(textureLoad(layer, vec2i(low.x, high.y), 0)),
    premultiplied(textureLoad(layer, high, 0)), weight.x);
  return mix(upper, lower, weight.y);
}


struct Surface {
  color: vec4f,
  normal: vec4f,
  outline: vec4f,
};
fn blend_surface(a: Surface, b: Surface, weight: f32) -> Surface {
  return Surface(mix(a.color, b.color, weight),
    mix(a.normal, b.normal, weight), mix(a.outline, b.outline, weight));
}
fn oct_normal(encoded: vec2f) -> vec3f {
  let xy = encoded * 2.0 - vec2f(1.0);
  var normal = vec3f(xy, 1.0 - abs(xy.x) - abs(xy.y));
  if (normal.z < 0.0) {
    let signs = select(vec2f(-1.0), vec2f(1.0), xy >= vec2f(0.0));
    normal = vec3f((vec2f(1.0) - abs(xy.yx)) * signs, normal.z);
  }
  return normalize(normal);
}
fn indexed_texel(at: vec2i) -> Surface {
  // Palette entries contain both straight albedo and outline coverage. Resolve
  // each index before filtering; interpolating index numbers corrupts colors.
  let index = i32(round(textureLoad(atlas, at, 0).r * 255.0));
  let color = textureLoad(outline_atlas, vec2i(index, 0), 0);
  let outline = textureLoad(outline_atlas, vec2i(index, 1), 0);
  let normal = oct_normal(textureLoad(normal_atlas, at, 0).rg);
  return Surface(premultiplied(color),
    vec4f((normal * 0.5 + vec3f(0.5)) * color.a, color.a),
    premultiplied(outline));
}
fn indexed_capture(frame: vec2u, uv: vec2f) -> Surface {
  let cell = vec2f(textureDimensions(atlas)) / vec2f(32.0, 17.0);
  let pixel = clamp(uv * cell, vec2f(0.5), cell - vec2f(0.5));
  let at = vec2f(frame) * cell + pixel - vec2f(0.5);
  let low = vec2i(floor(at));
  let high = min(low + vec2i(1), vec2i((vec2f(frame) + vec2f(1.0)) * cell) - vec2i(1));
  let weight = fract(at);
  let upper = blend_surface(indexed_texel(low), indexed_texel(vec2i(high.x, low.y)), weight.x);
  let lower = blend_surface(indexed_texel(vec2i(low.x, high.y)), indexed_texel(high), weight.x);
  return blend_surface(upper, lower, weight.y);
}
fn capture(frame: vec2u, point: vec3f) -> Surface {
  let uv = capture_uv(frame, point);
  if (draw.settings.w > 1.5) {
    return indexed_capture(frame, uv);
  }
  var surface: Surface;
  surface.color = filtered(atlas, frame, uv);
  if (draw.settings.z > 0.0) {
    // The renderer binds a linear view, so RGB is encoded XYZ, not sRGB.
    surface.normal = filtered(normal_atlas, frame, uv);
  }
  if (draw.settings.w > 0.0) {
    surface.outline = filtered(outline_atlas, frame, uv);
  }
  return surface;
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  let yaw = input.frame.x * (2.0 * 3.14159265359 / 32.0);
  let right_axis = vec3f(cos(yaw), 0.0, -sin(yaw));
  let up_axis = normalize(cross(input.direction, right_axis));
  let point = body_point(right_axis * ((input.uv.x - 0.5) * (5.0 / 7.0)) +
    up_axis * (0.5 - input.uv.y), input.direction);
  let base = vec2u(floor(input.frame));
  let left = base.x % 32u;
  let right = (left + 1u) % 32u;
  let top = min(base.y, 16u);
  let bottom = min(top + 1u, 16u);
  let weight = fract(input.frame);
  let upper = blend_surface(capture(vec2u(left, top), point),
    capture(vec2u(right, top), point), weight.x);
  let lower = blend_surface(capture(vec2u(left, bottom), point),
    capture(vec2u(right, bottom), point), weight.x);
  let surface = blend_surface(upper, lower, weight.y);
  var illumination = vec3f(1.0);
  if (draw.settings.x > 0.0 && surface.normal.a > 0.0) {
    let decoded = 2.0 * surface.normal.rgb / surface.normal.a - vec3f(1.0);
    if (dot(decoded, decoded) > 0.000001) {
      let local_normal = normalize(decoded);
      let normal = normalize(input.object_right * local_normal.x +
        input.object_up * local_normal.y + input.object_front * local_normal.z);
      let diffuse = max(dot(normal, normalize(-scene.light_direction.xyz)), 0.0);
      illumination = scene.ambient.xyz + scene.light_color.xyz * diffuse;
    }
  }
  // Outline coverage stays registered to its capture and is not darkened by
  // lighting. Composite in premultiplied space, then apply the crowd cutoff.
  let color = vec4f(surface.outline.rgb + surface.color.rgb * illumination *
    (1.0 - surface.outline.a),
    surface.outline.a + surface.color.a * (1.0 - surface.outline.a));
  // Ordinary blended materials keep smooth coverage transitions. Crowd
  // materials set a cutoff, letting surviving pixels write scene depth and
  // allowing every animation material to render as one instance batch.
  if (color.a <= 0.0 || color.a < draw.settings.y) {
    discard;
  }
  let coverage = select(color.a, 1.0, draw.settings.y > 0.0);
  return vec4f(draw.color.rgb * color.rgb / color.a, draw.color.a * coverage);
}

