// A strand of cartoon wind (src/wind.blot): a thin white stroke streaking
// across the sky, tapering at both ends, rising and falling gently along its
// way and sometimes looping the loop, as painted wind does. The strip it is
// drawn on (models/wind/wind.py) is laid along the strand's path here and
// turned to face the camera; the strand is the stretch of path it covers,
// sliding along as it flies.
//
// The draw's model matrix places the start of the path and turns it: the
// path runs along +x, up +y. A strand fades in over the start of its path and
// out toward its end, `path_length` along (src/wind.blot imports it).
struct Scene {
  view: mat4x4f,
  projection: mat4x4f,
  ambient: vec4f,
  light_direction: vec4f,
  light_color: vec4f,
  light_view_projection: mat4x4f,
  shadow: vec4f,
};
// What src/wind.blot passes each strand: how far along its path its head is,
// how long it is, where on the path it loops (below 0 for no loop) and how
// widely.
struct Parameters {
  head: f32,
  length: f32,
  loop_at: f32,
  radius: f32,
};
struct Draw {
  model: mat4x4f,
  normal: mat4x4f,
  color: vec4f,
  settings: vec4f,
  parameters: Parameters,
};
@group(0) @binding(0) var<uniform> scene: Scene;
@group(0) @binding(1) var shadow_map: texture_depth_2d;
@group(0) @binding(2) var shadow_sampler: sampler_comparison;
@group(1) @binding(0) var<uniform> draw: Draw;

struct VertexInput {
  @location(0) position: vec3f,
  @location(1) normal: vec3f,
  @location(2) uv: vec2f,
};
struct VertexOutput {
  @builtin(position) position: vec4f,
  // How far along the strand (0 its tail, 1 its head), and across it.
  @location(0) along: f32,
  @location(1) across: f32,
  // How far along its whole path, to fade in and out by.
  @location(2) travelled: f32,
};

// How wide a strand is, at its middle, and how long its whole path.
const width = 0.16;
const path_length = 60.0;

// The path at `u` units along it, in its own frame: on along +x, rising and
// falling gently and drifting a little aside; and, from `loop_at`, once round
// a loop of `radius` standing up from it, moving on a little as it goes round.
fn path(u: f32) -> vec3f {
  let loop_at = draw.parameters.loop_at;
  let radius = draw.parameters.radius;
  let wave = vec3f(0.0, 0.35 * sin(u * 0.45), 0.5 * sin(u * 0.21 + 1.3));
  if (loop_at < 0.0 || u < loop_at) {
    return vec3f(u, 0.0, 0.0) + wave;
  }
  let once_round = 6.2831853 * radius;
  let into = u - loop_at;
  if (into < once_round) {
    let a = into / radius;
    return vec3f(loop_at + into * 0.3 + radius * sin(a), radius * (1.0 - cos(a)), 0.0) + wave;
  }
  return vec3f(loop_at + once_round * 0.3 + (into - once_round), 0.0, 0.0) + wave;
}

@vertex fn vertex(input: VertexInput) -> VertexOutput {
  var output: VertexOutput;
  let along = input.uv.x;
  let head = draw.parameters.head;
  let u = head - draw.parameters.length * (1.0 - along);
  let here = (draw.model * vec4f(path(u), 1.0)).xyz;
  let ahead = (draw.model * vec4f(path(u + 0.05), 1.0)).xyz;
  let tangent = normalize(ahead - here + vec3f(0.00001, 0.0, 0.0));
  let rotation = mat3x3f(scene.view[0].xyz, scene.view[1].xyz, scene.view[2].xyz);
  let eye = -(transpose(rotation) * scene.view[3].xyz);
  let to_eye = normalize(eye - here);
  let side = normalize(cross(tangent, to_eye) + vec3f(0.0, 0.00001, 0.0));
  // Tapering to a point at both ends, fuller toward the head.
  let taper = pow(sin(3.14159265 * along), 0.8) * mix(0.6, 1.0, along);
  let world = here + side * input.uv.y * width * taper;
  output.position = scene.projection * scene.view * vec4f(world, 1.0);
  output.along = along;
  output.across = input.uv.y;
  output.travelled = u;
  return output;
}

@fragment fn fragment(input: VertexOutput) -> @location(0) vec4f {
  // Clean white, a touch of the sky's blue at its edges, its edges soft.
  let edge = abs(input.across);
  let color = mix(vec3f(1.0), vec3f(0.86, 0.93, 1.0), smoothstep(0.3, 1.0, edge));
  let fade = smoothstep(0.0, 4.0, input.travelled) * (1.0 - smoothstep(path_length - 10.0, path_length, input.travelled));
  let alpha = (1.0 - smoothstep(0.6, 1.0, edge)) * smoothstep(0.0, 0.08, input.along) * 0.9 * fade;
  return vec4f(color, alpha);
}

